@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800;900&family=Inter:wght@400;500;600;700;800;900&display=swap');
*{box-sizing:border-box}
/* ── TEMA OSCURO (default) — Aurora palette ─────────────────── */
:root {
  /* Aurora canonical tokens */
  --aurora-bg:#07050D;
  --aurora-panel:rgba(255,255,255,.035);
  --aurora-panel-strong:rgba(255,255,255,.055);
  --aurora-panel-soft:rgba(255,255,255,.025);
  --aurora-border:rgba(124,92,255,.16);
  --aurora-border-strong:rgba(124,92,255,.28);
  --aurora-violet:#7C5CFF;
  --aurora-violet-deep:#5B3FD1;
  --aurora-cyan:#33E6C4;
  --aurora-magenta:#FF4FA3;
  --aurora-magenta-deep:#C23B7A;
  --aurora-text:#F5F3FF;
  --aurora-dim:#9C97B8;
  /* Legacy aliases → Aurora */
  --bg:var(--aurora-bg);
  --panel:var(--aurora-panel);
  --panel2:var(--aurora-panel-strong);
  --panel3:rgba(255,255,255,.07);
  --line:var(--aurora-border);
  --line2:var(--aurora-border-strong);
  --text:var(--aurora-text);
  --muted:var(--aurora-dim);
  --muted2:#7B7694;
  --gold:var(--aurora-violet);
  --gold2:var(--aurora-cyan);
  --green:var(--aurora-cyan);
  --red:var(--aurora-magenta);
  --blue:var(--aurora-violet);
  --purple:var(--aurora-violet);
  --cyan:var(--aurora-cyan);
  --magenta:var(--aurora-magenta);
  --violet:var(--aurora-violet);
  --violet-deep:var(--aurora-violet-deep);
  --magenta-deep:var(--aurora-magenta-deep);
  --radius:20px;
  --shadow:0 18px 60px rgba(0,0,0,.38);
}

/* Trade export controls */
.journalQuickActions{flex-wrap:wrap}
.exportGroup,.tradeExportActions{display:inline-flex;align-items:center;gap:6px;flex-wrap:wrap}
.exportGroup{padding:6px;border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.025);border-radius:16px}
.tradeExportActions .ghost.compact{min-height:34px;padding:7px 9px!important}
.tradeDeleteButton{display:inline-grid!important;place-items:center!important;width:36px!important;height:36px!important;min-width:36px!important;max-width:36px!important;padding:0!important;border-radius:12px!important;border:1px solid rgba(244,63,94,.28)!important;background:rgba(244,63,94,.07)!important;color:#fecdd3!important;box-shadow:none!important;flex:0 0 36px!important}
.tradeDeleteButton:hover{border-color:rgba(244,63,94,.45)!important;background:rgba(244,63,94,.12)!important;color:#fff!important}
.modalActions .exportModalButton{display:inline-flex!important;align-items:center!important;justify-content:center!important;gap:7px!important;min-height:38px!important;padding:8px 11px!important;border:1px solid rgba(191,145,42,.35)!important;border-radius:12px!important;background:#fffaf0!important;color:#1f2937!important;font-size:12px!important;font-weight:900!important;box-shadow:0 8px 18px rgba(15,23,42,.06)!important}
.modalActions .exportModalButton svg{color:#b8860b!important}
.modalActions .exportModalButton:hover{border-color:rgba(191,145,42,.52)!important;background:#fff7e6!important;color:#111827!important}
html[data-theme="dark"] .modalActions .exportModalButton{border-color:rgba(212,175,55,.35)!important;background:rgba(15,23,42,.72)!important;color:#e5e7eb!important;box-shadow:0 10px 24px rgba(0,0,0,.24)!important}
html[data-theme="dark"] .modalActions .exportModalButton svg{color:#d4af37!important}
html[data-theme="dark"] .modalActions .exportModalButton:hover{border-color:rgba(212,175,55,.55)!important;background:rgba(212,175,55,.10)!important;color:#fff7db!important}
button:disabled,.ghost:disabled,.primary:disabled{opacity:.45;cursor:not-allowed;transform:none!important;box-shadow:none!important}
button:disabled:hover,.ghost:disabled:hover,.primary:disabled:hover{color:var(--muted);border-color:var(--line2);background:transparent}
@media(max-width:1050px){.tradeExportActions{width:auto;justify-content:flex-start}.exportGroup{width:100%}.exportGroup .ghost{flex:1 1 135px}}

/* ── TEMA CLARO ─────────────────────────────────────────────── */
:root[data-theme="light"] {
  --bg: #f0f2f5;
  --panel: #ffffff;
  --panel2: #f5f6f9;
  --panel3: #eaecf1;
  --line: rgba(0,0,0,.08);
  --line2: rgba(0,0,0,.13);
  --text: #0f1117;
  --muted: #4b5563;
  --muted2: #9ca3af;
  --gold: #b8860b;
  --gold2: #c99a1a;
  --green: #16a34a;
  --red: #e11d48;
  --blue: #2563eb;
  --purple: #6d28d9;
  --cyan: #0891b2;
  --radius: 18px;
  --shadow: 0 8px 32px rgba(0,0,0,.10);

  /* Nuevas variables para componentes premium */
  --hero-text: #1a1f2e;
  --hero-sub: #4b5563;
  --hero-label: #6b7280;
  --stat-value: #111827;
  --stat-label: #6b7280;
  --card-inner: #f8f9fb;
  --feed-item: #f5f6f9;
  --feed-border: rgba(0,0,0,.07);
  --msg-bg: #f0f2f6;
  --msg-self: rgba(184,134,11,.10);
}

/* ── Sobrescrituras modo claro: colores hardcodeados ─────────── */
:root[data-theme="light"] .side {
  background: linear-gradient(180deg, #ffffff, #f5f6f9) !important;
}
:root[data-theme="light"] .main {
  background: radial-gradient(circle at top right, rgba(212,168,67,.06), transparent 400px), #f0f2f5 !important;
}
:root[data-theme="light"] .top {
  background: rgba(240,242,245,.88) !important;
}
:root[data-theme="light"] .toolbar {
  background: rgba(240,242,245,.94) !important;
}
:root[data-theme="light"] .modal {
  background: rgba(0,0,0,.45) !important;
}
:root[data-theme="light"] .modalCard {
  background: #ffffff !important;
}
:root[data-theme="light"] .card {
  background: linear-gradient(180deg, #ffffff, #fafbfc) !important;
}
:root[data-theme="light"] .post,
:root[data-theme="light"] .idea {
  background: linear-gradient(180deg, #ffffff, #f8f9fb) !important;
}
:root[data-theme="light"] .metric {
  background: linear-gradient(180deg, #ffffff, #f8f9fb) !important;
}
:root[data-theme="light"] .login {
  background: radial-gradient(circle at top, rgba(212,168,67,.10), transparent 420px), #f0f2f5 !important;
}
:root[data-theme="light"] .loginCard {
  background: #ffffff !important;
}
:root[data-theme="light"] .heroSystem {
  background: linear-gradient(135deg, rgba(212,168,67,.12), rgba(240,242,245,.96)) !important;
}
:root[data-theme="light"] .mobileNav {
  background: rgba(255,255,255,.96) !important;
  border-color: rgba(212,168,67,.20) !important;
}
:root[data-theme="light"] .trade {
  background: #f5f6f9 !important;
}
:root[data-theme="light"] .rank,
:root[data-theme="light"] .adminRow,
:root[data-theme="light"] .notif {
  background: #f5f6f9 !important;
}
:root[data-theme="light"] .helpPanel {
  background: #ffffff !important;
}
:root[data-theme="light"] .toast {
  background: linear-gradient(135deg, #ffffff, #f8f9fb) !important;
  color: #0f1117 !important;
}
:root[data-theme="light"] .libraryBookPro {
  background: linear-gradient(135deg, #ffffff, #fafbfc) !important;
}
:root[data-theme="light"] .orLine span {
  background: #ffffff !important;
}
:root[data-theme="light"] ::-webkit-scrollbar-thumb {
  background: #c9cdd8 !important;
}

