  .metrics{grid-template-columns:1fr;gap:14px}
  .metric{padding:18px}
  .grid.two,.courseGrid,.ideaGrid{grid-template-columns:1fr}
  .quick{grid-template-columns:1fr 1fr}
  .card{padding:16px;border-radius:18px}
