/* v40.2 HOTFIX: PWA/mobile overscroll + no lateral movement */
html,body,#root{
  overscroll-behavior-y:none!important;
  overscroll-behavior-x:none!important;
  background:#07090D!important;
}
html{background-color:#07090D!important;overflow:hidden!important;height:100%;width:100%;}
body{
  background-color:#07090D!important;
  overflow:hidden!important;
  position:fixed!important;
  inset:0!important;
  width:100%!important;
  height:100%!important;
  min-height:100%!important;
  touch-action:manipulation;
}
#root{
  width:100%!important;
  height:100dvh!important;
  overflow:hidden!important;
}
.app{
  height:100dvh!important;
  min-height:100dvh!important;
  overflow:hidden!important;
  background:#07090D!important;
}
.main{
  height:100dvh!important;
  overflow-y:auto!important;
  overflow-x:hidden!important;
  -webkit-overflow-scrolling:touch;
  overscroll-behavior:contain!important;
  background:#07090D!important;
}
.page,.login,.modalCard,.side nav,.content,.pageWrap,.mainContent{
  overscroll-behavior:contain!important;
  -webkit-overflow-scrolling:touch;
}
*{max-width:100%;}
html,body,.app,.main,.page{overflow-x:hidden!important;}
@media(max-width:860px){
  .app{display:block!important;width:100vw!important;max-width:100vw!important;}
