   Keeps the logged-in app fixed, but restores normal vertical scrolling on public routes. */
html,
body,
#root{
  min-height:100%!important;
  height:auto!important;
  overflow-x:hidden!important;
  background:#07090D!important;
}

body:has(.publicLanding),
body:has(.authPage),
body:has(.login){
  overflow-y:auto!important;
  position:static!important;
  inset:auto!important;
  width:100%!important;
  touch-action:auto!important;
}

#root:has(.publicLanding),
#root:has(.authPage),
#root:has(.login){
  min-height:100dvh!important;
  height:auto!important;
  overflow-y:visible!important;
  overflow-x:hidden!important;
}

.publicLanding,
.landingPage,
.landingShell,
.authPage,
.login{
  min-height:100dvh!important;
  height:auto!important;
  max-height:none!important;
  overflow-y:visible!important;
  overflow-x:hidden!important;
  -webkit-overflow-scrolling:touch!important;
  overscroll-behavior-y:auto!important;
}

.landingHero{
  min-height:100dvh!important;
  height:auto!important;
  max-height:none!important;
  overflow:visible!important;
}

/* Re-apply fixed internal scroll only when the logged-in app exists. */
#root:has(.app) {
  height:100dvh!important;
  min-height:100dvh!important;
  overflow:hidden!important;
}

body:has(.app){
  height:100dvh!important;
  min-height:100dvh!important;
  overflow:hidden!important;
}

.app{
  height:100dvh!important;
  overflow:hidden!important;
}

.app .main,
.app .pageScroller,
.app .mainContent{
  overflow-y:auto!important;
  overflow-x:hidden!important;
  -webkit-overflow-scrolling:touch!important;
}

/* v40.7.3 HOTFIX — definitive public landing scroll */
/* The logged-in app intentionally owns its internal scroll, but public routes must scroll themselves. */
.publicLanding,
.landingPage,
.landingShell{
  display:block!important;
  height:100dvh!important;
  min-height:100dvh!important;
  max-height:none!important;
  overflow-y:auto!important;
  overflow-x:hidden!important;
  -webkit-overflow-scrolling:touch!important;
  overscroll-behavior-y:auto!important;
  touch-action:auto!important;
  position:relative!important;
}

.publicLanding .landingHero{
  height:auto!important;
  min-height:100dvh!important;
  overflow:visible!important;
}

.publicLanding *{
  overscroll-behavior:initial;
}

@media (min-width: 861px){
  .publicLanding,
  .landingPage,
  .landingShell{
    height:100vh!important;
    min-height:100vh!important;
    overflow-y:scroll!important;
    overflow-x:hidden!important;
    scrollbar-gutter:stable!important;
  }
}

