/* v46 — Commercial luxury UI polish */
:root{
  --premium-soft-shadow:0 24px 70px rgba(0,0,0,.34);
  --premium-ring:rgba(212,168,67,.22);
  --premium-glow:rgba(212,168,67,.12);
}
:root[data-theme="light"]{
  --bg:#eef1f6;
  --panel:#ffffff;
  --panel2:#f8fafc;
  --panel3:#eef2f7;
  --line:rgba(15,23,42,.105);
  --line2:rgba(15,23,42,.16);
  --text:#0b1220;
  --muted:#526174;
  --muted2:#7b8797;
  --gold:#c79625;
  --gold2:#9a6f12;
  --shadow:0 22px 55px rgba(15,23,42,.085);
  --premium-soft-shadow:0 24px 70px rgba(15,23,42,.10);
  --premium-ring:rgba(199,150,37,.24);
  --premium-glow:rgba(199,150,37,.10);
}

body{letter-spacing:-.01em;}
.app{background:var(--bg)!important;}
.main{position:relative;isolation:isolate;}
.main:before{content:'';position:fixed;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(circle at 86% 6%,rgba(212,168,67,.13),transparent 340px),radial-gradient(circle at 12% 12%,rgba(59,130,246,.08),transparent 300px),linear-gradient(135deg,rgba(255,255,255,.018) 0 25%,transparent 25% 50%,rgba(255,255,255,.012) 50% 75%,transparent 75%);background-size:auto,auto,34px 34px;opacity:.9;}
.page{padding:28px 32px 72px!important;}

/* Global premium surfaces */
.card,.metric,.post,.idea,.trade,.rank,.adminRow,.notif,.brokerHero,.brokerHeroPanel,.comingSoonItem,.brokerFlow div,.syncHistory>div,.input,.search,.toolbar,.modalCard,.loginCard,.paywallCard,.academyLesson,.onlineRow,.checkItem,.monthCell,.behaviorScoreBox,.behaviorMetrics div,.proTable>div{
  border-width:1px!important;
  border-style:solid!important;
}
.card,.metric,.post,.idea,.trade,.rank,.adminRow,.notif,.brokerHeroPanel,.comingSoonItem,.brokerFlow div,.syncHistory>div,.academyLesson,.onlineRow,.checkItem{
  position:relative;
  overflow:hidden;
}
.card:after,.metric:after,.brokerFlow div:after,.comingSoonItem:after,.idea:after,.post:after,.trade:after,.academyLesson:after{
  content:'';position:absolute;left:0;right:0;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(255,255,255,.18),transparent);pointer-events:none;
}
.card:hover,.metric:hover,.idea:hover,.post:hover,.trade:hover,.comingSoonItem:hover,.brokerFlow div:hover,.academyLesson:hover{
  transform:translateY(-1px);
}

/* Sidebar + header: more expensive, less flat */
.side{box-shadow:14px 0 45px rgba(0,0,0,.18);}
.brand{min-height:88px;}
.brandLogo{border-radius:16px!important;box-shadow:0 14px 34px rgba(0,0,0,.28),0 0 0 4px rgba(212,168,67,.06)!important;}
.navGroup{position:relative;padding-top:8px;margin-top:8px;}
.navGroup+ .navGroup{border-top:1px solid var(--line);}
.navGroup small{display:block;margin:0 12px 8px;color:var(--muted2);font-size:10px;letter-spacing:.18em;font-weight:900;text-transform:uppercase;}
nav button{min-height:42px;position:relative;transition:background .18s ease,border-color .18s ease,color .18s ease,transform .18s ease;}
nav button:hover{transform:translateX(2px);}
nav button.active:before{content:'';position:absolute;left:0;top:9px;bottom:9px;width:3px;border-radius:999px;background:linear-gradient(180deg,var(--gold2),var(--gold));box-shadow:0 0 18px var(--premium-glow);}
.top{min-height:76px;box-shadow:0 12px 32px rgba(0,0,0,.10);}
.top h1{font-size:24px!important;letter-spacing:-.045em!important;font-weight:900!important;}
.topActions button,.topCta,.crownBadge,.cmdHint{box-shadow:0 10px 24px rgba(0,0,0,.09);}
.primary{box-shadow:0 16px 30px rgba(212,168,67,.22)!important;transition:transform .18s ease,box-shadow .18s ease,filter .18s ease!important;}
.primary:hover{transform:translateY(-1px);box-shadow:0 20px 36px rgba(212,168,67,.28)!important;}
.ghost{transition:transform .18s ease,border-color .18s ease,background .18s ease!important;}
.ghost:hover{transform:translateY(-1px);border-color:rgba(212,168,67,.25)!important;background:rgba(212,168,67,.06)!important;color:var(--text)!important;}

