/* ═══════════════════════════════════════════════════════════════════════════
   MOISÉS TRADING CLUB — CSS v47 (Landing + Paywall)
   Prefijos: lv47- (landing) y pw47- (paywall)
   Agregar al FINAL de src/styles.css — no toca ninguna clase existente.
   ═══════════════════════════════════════════════════════════════════════════ */

/* ─── TOKENS ──────────────────────────────────────────────────────────────── */
:root{
  --g-gold:#C9913D;
  --g-gold-light:#E8C97B;
  --g-gold-dim:rgba(201,145,61,.14);
  --g-gold-border:rgba(201,145,61,.28);
  --g-bg:#060810;
  --g-surface:rgba(255,255,255,.042);
  --g-surface-hover:rgba(255,255,255,.065);
  --g-border:rgba(255,255,255,.08);
  --g-border-gold:rgba(201,145,61,.22);
  --g-text:#F4EEE0;
  --g-text-muted:#8B95A8;
  --g-text-subtle:#5C6477;
  --g-green:#2FCE8A;
  --g-radius-sm:12px;
  --g-radius-md:18px;
  --g-radius-lg:24px;
  --g-radius-xl:32px;
}

/* ─── EYEBROW ─────────────────────────────────────────────────────────────── */
.lv47-eyebrow,.pw47-eyebrow{
  display:inline-block;
  font-size:11px;font-weight:900;
  letter-spacing:.18em;text-transform:uppercase;
  color:var(--g-gold);
  margin-bottom:14px;
}
.lv47-eyebrow--light{color:rgba(201,145,61,.7)}

/* ─── SHARED BUTTONS ──────────────────────────────────────────────────────── */
.lv47-btn{
  display:inline-flex;align-items:center;gap:9px;
  padding:14px 22px;
  border-radius:var(--g-radius-sm);
  font-size:15px;font-weight:900;
  cursor:pointer;
  transition:transform .14s ease,box-shadow .14s ease,opacity .14s ease;
  border:none;
}
.lv47-btn:hover{transform:translateY(-1px)}
.lv47-btn:active{transform:scale(.98)}
.lv47-btn--primary{
  background:linear-gradient(135deg,#D9A040,#B87922);
  color:#130e02;
  box-shadow:0 12px 28px rgba(201,145,61,.28);
}
.lv47-btn--primary:hover{box-shadow:0 18px 38px rgba(201,145,61,.38)}
.lv47-btn--ghost{
  background:rgba(255,255,255,.06);
  border:1px solid var(--g-border);
  color:var(--g-text);
}
.lv47-btn--ghost:hover{background:rgba(255,255,255,.09)}
.lv47-btn--lg{padding:16px 28px;font-size:16px;border-radius:var(--g-radius-md)}

/* ══════════════════════════════════════════════════════════════════════════
   LANDING v47
   ══════════════════════════════════════════════════════════════════════════ */

.lv47-landing{
  min-height:100dvh;
  background:#060810;
  color:var(--g-text);
  overflow-x:hidden;
}

/* ─── HERO ────────────────────────────────────────────────────────────────── */
.lv47-hero{
  position:relative;
  padding:64px clamp(20px,5vw,80px) 0;
  max-width:1440px;
  margin:0 auto;
}
.lv47-hero__glow{
  position:absolute;
  top:-80px;left:5%;
  width:640px;height:640px;
  background:radial-gradient(circle,rgba(201,145,61,.13),transparent 65%);
  pointer-events:none;
  filter:blur(8px);
}
.lv47-hero__grid{
  position:fixed;inset:0;
  background-image:
    linear-gradient(rgba(255,255,255,.022) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.022) 1px,transparent 1px);
  background-size:52px 52px;
  mask-image:radial-gradient(ellipse at 50% 0,black 20%,transparent 70%);
  pointer-events:none;
  z-index:0;
}
.lv47-hero__content{
  position:relative;z-index:1;
  display:grid;
  grid-template-columns:minmax(0,1.1fr) minmax(380px,.9fr);
  gap:clamp(32px,5vw,80px);
  align-items:center;
  min-height:min(720px,calc(100dvh - 60px));
}
.lv47-hero__badge{
  display:inline-flex;align-items:center;gap:8px;
  padding:8px 14px;
  border-radius:999px;
  background:rgba(201,145,61,.08);
  border:1px solid var(--g-gold-border);
  color:var(--g-gold-light);
  font-size:11px;font-weight:900;
  letter-spacing:.10em;text-transform:uppercase;
  margin-bottom:26px;
}
.lv47-hero__h1{
  font-size:clamp(48px,6.5vw,88px);
  line-height:.91;
  letter-spacing:-.075em;
  color:#FFF5DC;
  margin:0 0 22px;
  text-wrap:balance;
}
.lv47-hero__h1 em{
  font-style:normal;
  background:linear-gradient(120deg,#E8C97B,#C9913D);
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  background-clip:text;
}
.lv47-hero__sub{
  font-size:clamp(16px,1.8vw,20px);
  line-height:1.68;
  color:var(--g-text-muted);
  max-width:560px;
  margin:0 0 32px;
}
.lv47-hero__actions{
  display:flex;gap:12px;flex-wrap:wrap;
  margin-bottom:16px;
}
.lv47-hero__micro{
  font-size:12px;
  color:var(--g-text-subtle);
  letter-spacing:.02em;
}

/* ── Dashboard mockup ── */
.lv47-mockdash{
  border:1px solid var(--g-border-gold);
  border-radius:var(--g-radius-xl);
  background:linear-gradient(160deg,rgba(16,18,26,.98),rgba(8,9,14,.98));
  box-shadow:0 40px 100px rgba(0,0,0,.52),0 0 0 1px rgba(255,255,255,.04) inset;
  overflow:hidden;
}
.lv47-mockdash__bar{
  display:flex;align-items:center;gap:8px;
  padding:14px 18px;
  border-bottom:1px solid var(--g-border);
  background:rgba(255,255,255,.03);
}
.lv47-mockdash__dot{
  width:9px;height:9px;
  border-radius:50%;
  background:rgba(255,255,255,.14);
}
.lv47-mockdash__title{
  flex:1;
  font-size:12px;font-weight:800;
  color:rgba(255,255,255,.5);
  letter-spacing:.06em;
  text-transform:uppercase;
}
.lv47-mockdash__live{
  display:inline-flex;align-items:center;gap:6px;
  font-size:10px;font-weight:900;
  letter-spacing:.12em;
  color:var(--g-green);
  text-transform:uppercase;
}
.lv47-mockdash__live span{
  width:6px;height:6px;
  border-radius:50%;
  background:var(--g-green);
  box-shadow:0 0 6px var(--g-green);
}
.lv47-mockdash__body{
  padding:20px;
  display:grid;gap:16px;
}
.lv47-mockdash__kpis{
  display:grid;grid-template-columns:repeat(3,1fr);gap:10px;
}
.lv47-kpi{
  padding:14px;
  border-radius:var(--g-radius-sm);
  background:var(--g-surface);
  border:1px solid var(--g-border);
}
.lv47-kpi__label{
  display:block;
  font-size:10px;font-weight:800;
  letter-spacing:.08em;text-transform:uppercase;
  color:var(--g-text-subtle);
  margin-bottom:6px;
}
.lv47-kpi__val{
  display:block;
  font-size:24px;font-weight:900;
  letter-spacing:-.04em;
  color:#F4EEE0;
}
.lv47-kpi__val--green{color:var(--g-green)}
.lv47-kpi__val--gold{color:var(--g-gold-light)}
.lv47-mockdash__curve{
  padding:14px;
  border-radius:var(--g-radius-sm);
  background:var(--g-surface);
  border:1px solid var(--g-border);
  overflow:hidden;
}
.lv47-mockdash__curve svg{
  width:100%;height:auto;display:block;
}
.lv47-mockdash__curve-label{
  font-size:10px;font-weight:700;
  letter-spacing:.07em;text-transform:uppercase;
  color:var(--g-text-subtle);
  margin-top:8px;
}
.lv47-mockdash__heat-label{
  font-size:10px;font-weight:800;
  letter-spacing:.08em;text-transform:uppercase;
  color:var(--g-text-subtle);
}
.lv47-mockdash__heat{
  display:grid;
  grid-template-columns:repeat(7,1fr);
  gap:4px;
}
.lv47-heat-cell{
  height:20px;
  border-radius:4px;
  background:var(--g-gold);
}

/* ── proof bar ── */
.lv47-proof-bar{
  position:relative;z-index:1;
  display:grid;grid-template-columns:repeat(3,1fr);
  gap:1px;
  background:var(--g-border);
  border-top:1px solid var(--g-border);
  border-bottom:1px solid var(--g-border);
  margin-top:64px;
}
.lv47-proof-bar__item{
  padding:28px 32px;
  background:#060810;
  text-align:center;
}
.lv47-proof-bar__item b{
  display:block;
  font-size:clamp(28px,4vw,44px);
  font-weight:900;
  letter-spacing:-.05em;
  color:var(--g-gold-light);
  line-height:1;
}
.lv47-proof-bar__item span{
  display:block;
  font-size:13px;
  color:var(--g-text-subtle);
  margin-top:6px;
  line-height:1.45;
}

/* ─── STATEMENT ───────────────────────────────────────────────────────────── */
.lv47-statement{
  padding:96px clamp(20px,5vw,80px);
  max-width:1000px;margin:0 auto;
}
.lv47-statement__h2{
  font-size:clamp(28px,4.5vw,56px);
  line-height:1.08;
  letter-spacing:-.055em;
  color:#FFF5DC;
  margin:0 0 22px;
  text-wrap:balance;
}
.lv47-statement__h2 em{
  font-style:normal;
  color:var(--g-gold-light);
}
.lv47-statement__body{
  font-size:clamp(16px,1.6vw,19px);
  line-height:1.72;
  color:var(--g-text-muted);
  max-width:760px;
}

/* ─── PILLARS ─────────────────────────────────────────────────────────────── */
.lv47-pillars{
  padding:0 clamp(20px,5vw,80px) 80px;
  background:linear-gradient(180deg,transparent,rgba(201,145,61,.04) 40%,transparent);
}
.lv47-pillars__inner{max-width:1280px;margin:0 auto}
.lv47-pillars__h2{
  font-size:clamp(26px,3.5vw,46px);
  letter-spacing:-.05em;
  color:#FFF5DC;
  margin:0 0 40px;
}
.lv47-pillars__grid{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:16px;
}
.lv47-pillar{
  padding:28px 28px 24px;
  border:1px solid var(--g-border);
  border-radius:var(--g-radius-lg);
  background:linear-gradient(160deg,rgba(255,255,255,.048),rgba(255,255,255,.018));
  display:flex;flex-direction:column;gap:12px;
  transition:border-color .2s,transform .2s;
}
.lv47-pillar:hover{
  border-color:var(--g-gold-border);
  transform:translateY(-2px);
}
.lv47-pillar__icon{
  width:42px;height:42px;
  border-radius:var(--g-radius-sm);
  background:var(--g-gold-dim);
  border:1px solid var(--g-gold-border);
  display:grid;place-items:center;
  color:var(--g-gold-light);
}
.lv47-pillar__kicker{
  font-size:11px;font-weight:900;
  letter-spacing:.12em;text-transform:uppercase;
  color:var(--g-gold);
}
.lv47-pillar__title{
  font-size:clamp(18px,2vw,22px);
  font-weight:900;
  letter-spacing:-.04em;
  color:#FFF5DC;
  margin:0;
  line-height:1.2;
}
.lv47-pillar__body{
  font-size:14px;
  line-height:1.65;
  color:var(--g-text-muted);
  margin:0;
  flex:1;
}
.lv47-pillar__tag{
  display:inline-block;
  padding:6px 12px;
  border-radius:999px;
  background:rgba(255,255,255,.055);
  border:1px solid var(--g-border);
  font-size:11px;font-weight:800;
  color:rgba(255,255,255,.55);
  letter-spacing:.06em;
  align-self:flex-start;
}

/* ─── OUTCOMES ────────────────────────────────────────────────────────────── */
.lv47-outcomes{
  padding:80px clamp(20px,5vw,80px);
}
.lv47-outcomes__inner{
  max-width:1280px;margin:0 auto;
  display:grid;
  grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr);
  gap:clamp(40px,6vw,96px);
  align-items:start;
}
.lv47-outcomes__h2{
  font-size:clamp(26px,3.5vw,46px);
  letter-spacing:-.055em;
  color:#FFF5DC;
  margin:0 0 18px;
  line-height:1.08;
}
.lv47-outcomes__h2 em{
  font-style:normal;
  color:var(--g-gold-light);
}
.lv47-outcomes__body{
  font-size:15px;
  line-height:1.68;
  color:var(--g-text-muted);
  margin:0 0 28px;
}
.lv47-outcomes__list{
  list-style:none;margin:0;padding:0;
  display:grid;gap:2px;
}
.lv47-outcomes__item{
  display:flex;align-items:center;gap:12px;
  padding:14px 16px;
  border-radius:var(--g-radius-sm);
  background:rgba(255,255,255,.028);
  border:1px solid transparent;
  transition:background .15s,border-color .15s;
}
.lv47-outcomes__item:hover{
  background:var(--g-surface-hover);
  border-color:var(--g-border);
}
.lv47-outcomes__item svg{
  flex:0 0 auto;
  color:var(--g-gold);
}
.lv47-outcomes__item span{
  font-size:14px;font-weight:700;
  color:#E8E0D0;
}

/* ─── AFTER ───────────────────────────────────────────────────────────────── */
.lv47-after{
  padding:80px clamp(20px,5vw,80px);
  background:rgba(255,255,255,.018);
  border-top:1px solid var(--g-border);
  border-bottom:1px solid var(--g-border);
}
.lv47-after__inner{max-width:1000px;margin:0 auto}
.lv47-after__h2{
  font-size:clamp(26px,3.5vw,44px);
  letter-spacing:-.05em;
  color:#FFF5DC;
  margin:0 0 44px;
}
.lv47-after__steps{
  display:grid;gap:0;
}
.lv47-after__step{
  display:grid;
  grid-template-columns:56px 1fr;
  gap:20px;
  padding:24px 0;
  border-bottom:1px solid var(--g-border);
}
.lv47-after__step:last-child{border-bottom:none}
.lv47-after__step-n{
  font-size:12px;font-weight:900;
  letter-spacing:.14em;
  color:var(--g-gold);
  padding-top:4px;
  text-align:right;
}
.lv47-after__step-title{
  font-size:clamp(16px,1.8vw,20px);
  font-weight:900;
  letter-spacing:-.035em;
  color:#FFF5DC;
  margin:0 0 8px;
}
.lv47-after__step-body{
  font-size:14px;
  line-height:1.62;
  color:var(--g-text-muted);
  margin:0;
}

/* ─── FINAL CTA ───────────────────────────────────────────────────────────── */
.lv47-final{
  padding:96px clamp(20px,5vw,80px);
  text-align:center;
  position:relative;
  overflow:hidden;
}
.lv47-final__glow{
  position:absolute;
  top:50%;left:50%;
  transform:translate(-50%,-50%);
  width:600px;height:400px;
  background:radial-gradient(circle,rgba(201,145,61,.11),transparent 65%);
  pointer-events:none;
}
.lv47-final__inner{
  position:relative;z-index:1;
  max-width:760px;margin:0 auto;
}
.lv47-final__h2{
  font-size:clamp(32px,5vw,64px);
  letter-spacing:-.07em;
  line-height:.95;
  color:#FFF5DC;
  margin:0 0 22px;
  text-wrap:balance;
}
.lv47-final__body{
  font-size:clamp(16px,1.7vw,19px);
  line-height:1.68;
  color:var(--g-text-muted);
  margin:0 0 36px;
}
.lv47-final__actions{
  display:flex;justify-content:center;gap:12px;flex-wrap:wrap;
  margin-bottom:20px;
}
.lv47-final__trust{
  display:inline-flex;align-items:center;gap:8px;
  font-size:12px;
  color:var(--g-text-subtle);
}
.lv47-final__trust svg{color:var(--g-gold)}

/* ─── LANDING RESPONSIVE ─────────────────────────────────────────────────── */
@media(max-width:1024px){
  .lv47-hero__content{grid-template-columns:1fr;min-height:auto;gap:40px;padding-bottom:40px}
  .lv47-pillars__grid{grid-template-columns:1fr}
  .lv47-outcomes__inner{grid-template-columns:1fr}
  .lv47-proof-bar{grid-template-columns:1fr;gap:0}
  .lv47-proof-bar__item{border-bottom:1px solid var(--g-border)}
}
@media(max-width:640px){
  .lv47-hero{padding:40px 16px 0}
  .lv47-hero__actions,.lv47-final__actions{flex-direction:column;width:100%}
  .lv47-btn{width:100%;justify-content:center}
  .lv47-mockdash__kpis{grid-template-columns:1fr}
  .lv47-statement,.lv47-pillars,.lv47-outcomes,.lv47-after,.lv47-final{padding-left:16px;padding-right:16px}
  .lv47-after__step{grid-template-columns:40px 1fr;gap:12px}
}


/* ══════════════════════════════════════════════════════════════════════════
   PAYWALL (AccessGate) v47
   ══════════════════════════════════════════════════════════════════════════ */

.pw47-root{
  min-height:100dvh;
  position:relative;
  display:grid;place-items:start center;
  padding:24px 16px 48px;
  background:#030507;
  color:var(--g-text);
  overflow-x:hidden;
}
.pw47-bg{
  position:fixed;inset:0;
  pointer-events:none;
  overflow:hidden;
}
.pw47-bg__glow{
  position:absolute;
  border-radius:50%;
  filter:blur(80px);
}
.pw47-bg__glow--gold{
  width:500px;height:400px;
  background:rgba(201,145,61,.12);
  top:-60px;left:-80px;
}
.pw47-bg__glow--blue{
  width:440px;height:440px;
  background:rgba(28,78,160,.09);
  top:40px;right:-60px;
}
.pw47-bg__grid{
  position:absolute;inset:0;
  background-image:
    linear-gradient(rgba(255,255,255,.016) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.016) 1px,transparent 1px);
  background-size:44px 44px;
  mask-image:radial-gradient(ellipse at 50% 10%,black,transparent 68%);
}

/* ── shell ── */
.pw47-shell{
  position:relative;z-index:1;
  width:min(1280px,100%);
  display:grid;gap:0;
}

/* ── header ── */
.pw47-header{
  display:flex;align-items:center;justify-content:space-between;gap:16px;
  padding:18px 0 22px;
  border-bottom:1px solid var(--g-border);
  margin-bottom:36px;
}
.pw47-header__brand{
  display:flex;align-items:center;gap:12px;
}
.pw47-header__brand img{
  width:42px;height:42px;
  border-radius:12px;
  border:1px solid var(--g-gold-border);
  object-fit:cover;
}
.pw47-header__brand b{
  display:block;font-size:14px;color:#FFF5DC;
}
.pw47-header__brand span{
  display:block;font-size:11px;color:var(--g-text-muted);margin-top:1px;
}
.pw47-header__right{
  display:flex;align-items:center;gap:10px;
}
.pw47-status{
  padding:7px 13px;
  border-radius:999px;
  font-size:11px;font-weight:900;
  letter-spacing:.12em;text-transform:uppercase;
  background:rgba(201,145,61,.10);
  border:1px solid var(--g-gold-border);
  color:var(--g-gold-light);
}
.pw47-status--approved{background:rgba(47,206,138,.10);border-color:rgba(47,206,138,.26);color:#6EEFC2}
.pw47-header__signout{
  display:inline-flex;align-items:center;gap:7px;
  padding:8px 14px;
  border-radius:10px;
  border:1px solid var(--g-border);
  background:var(--g-surface);
  color:rgba(255,255,255,.6);
  font-size:13px;font-weight:800;
  cursor:pointer;
  transition:background .14s;
}
.pw47-header__signout:hover{background:var(--g-surface-hover);color:var(--g-text)}

/* ── hero ── */
.pw47-hero{
  margin-bottom:28px;
}
.pw47-hero__h1{
  font-size:clamp(36px,5vw,62px);
  line-height:.94;
  letter-spacing:-.07em;
  color:#FFF5DC;
  margin:0 0 14px;
}
.pw47-hero__sub{
  font-size:clamp(15px,1.6vw,18px);
  line-height:1.62;
  color:var(--g-text-muted);
  margin:0 0 18px;
  max-width:640px;
}
.pw47-hero__chips{
  display:flex;flex-wrap:wrap;gap:8px;
}
.pw47-hero__chips span{
  display:inline-flex;align-items:center;gap:7px;
  padding:8px 13px;
  border-radius:999px;
  background:rgba(255,255,255,.04);
  border:1px solid var(--g-border);
  font-size:12px;font-weight:800;
  color:#DDD5C3;
}
.pw47-hero__chips svg{color:var(--g-gold);flex:0 0 auto}

/* ── billing cycle ── */
.pw47-billing{
  display:flex;align-items:center;justify-content:space-between;gap:20px;
  padding:18px 22px;
  border-radius:var(--g-radius-md);
  background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.02));
  border:1px solid var(--g-border);
  margin-bottom:22px;
}
.pw47-billing__label b{
  display:block;font-size:14px;color:#FFF5DC;
}
.pw47-billing__label span{
  display:block;font-size:12px;color:var(--g-text-muted);margin-top:3px;
}
.pw47-billing__options{
  display:flex;gap:6px;
  padding:6px;
  border-radius:14px;
  background:rgba(0,0,0,.3);
  border:1px solid var(--g-border);
}
.pw47-billing__btn{
  position:relative;
  min-width:110px;
  padding:10px 14px;
  border-radius:10px;
  border:none;
  background:transparent;
  color:var(--g-text-muted);
  cursor:pointer;
  text-align:center;
  transition:background .15s,color .15s;
}
.pw47-billing__btn b{
  display:block;font-size:13px;font-weight:900;
}
.pw47-billing__btn small{
  display:block;font-size:10px;margin-top:2px;
}
.pw47-billing__btn.active{
  background:linear-gradient(135deg,#D9A040,#B87922);
  color:#130e02;
  box-shadow:0 8px 20px rgba(201,145,61,.22);
}
.pw47-billing__btn.active small{color:#3d2301}
.pw47-billing__badge{
  position:absolute;
  top:-8px;right:-4px;
  padding:2px 7px;
  border-radius:999px;
  background:var(--g-gold);
  color:#0d0800;
  font-size:9px;font-weight:900;
  letter-spacing:.06em;
}

/* ── notice ── */
.pw47-notice{
  display:flex;align-items:center;gap:10px;
  padding:13px 16px;
  border-radius:14px;
  background:rgba(244,63,94,.09);
  border:1px solid rgba(244,63,94,.20);
  color:#fecdd3;
  font-size:13px;
  margin-bottom:20px;
}
.pw47-notice svg{flex:0 0 auto;color:#f43f5e}

/* ── main layout ── */
.pw47-layout{
  display:grid;
  grid-template-columns:minmax(0,1.2fr) minmax(320px,.8fr);
  gap:24px;
  align-items:start;
}
.pw47-plans-col{
  display:grid;gap:16px;
}

/* ── plans row (Club + Pro) ── */
.pw47-plans-row{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:14px;
}

/* ── plan card ── */
.pw47-plan{
  position:relative;
  display:flex;flex-direction:column;gap:16px;
  padding:22px;
  border-radius:var(--g-radius-lg);
  border:1px solid var(--g-border);
  background:linear-gradient(160deg,rgba(18,20,28,.98),rgba(8,10,14,.98));
  box-shadow:0 20px 60px rgba(0,0,0,.24);
  cursor:pointer;
  transition:transform .18s,border-color .18s,box-shadow .18s;
}
.pw47-plan:hover,.pw47-plan--selected{
  transform:translateY(-2px);
  border-color:var(--g-gold-border);
  box-shadow:0 28px 80px rgba(0,0,0,.36),0 0 0 1px rgba(201,145,61,.07) inset;
}
.pw47-plan--pro{
  background:radial-gradient(circle at 70% 0,rgba(201,145,61,.2),transparent 40%),
    linear-gradient(160deg,rgba(28,22,10,.98),rgba(8,10,14,.98));
  border-color:rgba(201,145,61,.36);
}
.pw47-plan__badge{
  position:absolute;top:14px;right:14px;
  display:inline-flex;align-items:center;gap:5px;
  padding:6px 12px;
  border-radius:999px;
  background:rgba(201,145,61,.15);
  border:1px solid var(--g-gold-border);
  color:var(--g-gold-light);
  font-size:10px;font-weight:900;
  letter-spacing:.08em;text-transform:uppercase;
}
.pw47-plan__top{
  padding-right:80px;
}
.pw47-plan__kicker{
  display:inline-block;
  padding:5px 10px;
  border-radius:999px;
  background:rgba(255,255,255,.05);
  border:1px solid var(--g-border);
  font-size:10px;font-weight:900;
  letter-spacing:.10em;text-transform:uppercase;
  color:var(--g-gold);
  margin-bottom:10px;
}
.pw47-plan__name{
  font-size:32px;
  font-weight:900;
  letter-spacing:-.045em;
  color:#FFF5DC;
  margin:0 0 6px;
}
.pw47-plan__headline{
  font-size:13px;
  line-height:1.5;
  color:var(--g-text-muted);
  margin:0;
}
.pw47-plan__price{
  padding:16px;
  border-radius:var(--g-radius-sm);
  background:rgba(255,255,255,.042);
  border:1px solid var(--g-border);
}
.pw47-plan__price--pro{
  background:linear-gradient(180deg,rgba(201,145,61,.12),rgba(255,255,255,.018));
  border-color:rgba(201,145,61,.22);
}
.pw47-plan__price s{
  display:block;
  font-size:12px;
  color:var(--g-text-subtle);
}
.pw47-plan__price b{
  display:block;
  font-size:42px;
  font-weight:900;
  letter-spacing:-.055em;
  color:#FFF5DC;
  line-height:.95;
}
.pw47-plan__price em{
  display:block;
  margin-top:6px;
  font-style:normal;
  font-size:11px;font-weight:900;
  letter-spacing:.12em;text-transform:uppercase;
  color:var(--g-gold);
}
.pw47-plan__price small{
  display:block;
  margin-top:5px;
  font-size:11px;
  color:var(--g-text-subtle);
}
.pw47-plan__value{
  font-size:12px;
  line-height:1.55;
  color:var(--g-text-muted);
  margin:0;
  min-height:36px;
}
.pw47-plan__features{
  list-style:none;margin:0;padding:0;
  display:grid;gap:9px;
  flex:1;
}
.pw47-plan__features li{
  display:flex;gap:9px;align-items:flex-start;
  font-size:13px;
  color:#D8D0BF;
  line-height:1.42;
}
.pw47-plan__features li svg{
  flex:0 0 auto;
  color:var(--g-gold);
  margin-top:1px;
}
.pw47-plan__cta{
  min-height:48px;
  border-radius:14px;
  font-size:14px;font-weight:900;
  cursor:pointer;
  display:flex;align-items:center;justify-content:center;gap:8px;
  transition:transform .14s,opacity .14s,box-shadow .14s;
  border:none;
}
.pw47-plan__cta:hover{transform:translateY(-1px)}
.pw47-plan__cta:disabled{opacity:.5;cursor:not-allowed;transform:none}
.pw47-plan__cta--primary{
  background:linear-gradient(135deg,#D9A040,#B87922);
  color:#130e02;
  box-shadow:0 14px 30px rgba(201,145,61,.22);
}
.pw47-plan__cta--primary:hover{box-shadow:0 18px 38px rgba(201,145,61,.34)}
.pw47-plan__cta--secondary{
  background:rgba(255,255,255,.055);
  border:1px solid var(--g-border);
  color:#E8E0D0;
}
.pw47-plan__cta--secondary:hover{background:rgba(255,255,255,.08)}

/* ── ROI note ── */
.pw47-roi{
  display:flex;gap:12px;
  padding:16px 18px;
  border-radius:var(--g-radius-sm);
  background:rgba(201,145,61,.06);
  border:1px solid rgba(201,145,61,.14);
  font-size:13px;
  color:rgba(232,201,123,.8);
  line-height:1.55;
}
.pw47-roi__icon{
  flex:0 0 auto;
  color:var(--g-gold);
  padding-top:1px;
}
.pw47-roi b{color:var(--g-gold-light)}

/* ── mentorship card ── */
.pw47-mentor{
  display:grid;
  grid-template-columns:1fr auto;
  gap:24px;
  padding:24px;
  border-radius:var(--g-radius-md);
  border:1px solid rgba(255,255,255,.10);
  background:linear-gradient(135deg,rgba(255,255,255,.042),rgba(255,255,255,.018));
  align-items:center;
}
.pw47-mentor__kicker{
  display:inline-flex;align-items:center;gap:6px;
  font-size:10px;font-weight:900;
  letter-spacing:.10em;text-transform:uppercase;
  color:var(--g-text-subtle);
  margin-bottom:8px;
}
.pw47-mentor__name{
  font-size:22px;font-weight:900;
  letter-spacing:-.04em;
  color:#FFF5DC;
  margin:0 0 6px;
}
.pw47-mentor__headline{
  font-size:13px;line-height:1.5;
  color:var(--g-text-muted);
  margin:0 0 14px;
}
.pw47-mentor__features{
  list-style:none;margin:0;padding:0;
  display:flex;flex-wrap:wrap;gap:6px;
}
.pw47-mentor__features li{
  display:inline-flex;align-items:center;gap:6px;
  padding:5px 10px;
  border-radius:999px;
  background:rgba(255,255,255,.05);
  border:1px solid var(--g-border);
  font-size:11px;font-weight:700;
  color:#C8C0AF;
}
.pw47-mentor__features li svg{color:var(--g-gold);flex:0 0 auto}
.pw47-mentor__right{text-align:right}
.pw47-mentor__price{
  margin-bottom:8px;
}
.pw47-mentor__price b{
  font-size:36px;font-weight:900;
  letter-spacing:-.05em;
  color:#FFF5DC;
}
.pw47-mentor__price em{
  font-style:normal;font-size:14px;
  color:var(--g-text-muted);
  margin-left:4px;
}
.pw47-mentor__note{
  font-size:11px;
  color:var(--g-text-subtle);
  margin:0 0 16px;
  line-height:1.45;
}
.pw47-mentor__cta{
  display:inline-flex;align-items:center;gap:8px;
  padding:12px 20px;
  border-radius:var(--g-radius-sm);
  background:rgba(255,255,255,.07);
  border:1px solid var(--g-border);
  color:#E8E0D0;
  font-size:13px;font-weight:900;
  cursor:pointer;
  transition:background .15s;
  white-space:nowrap;
}
.pw47-mentor__cta:hover{background:rgba(255,255,255,.11);border-color:rgba(255,255,255,.18)}

/* ── proof sidebar ── */
.pw47-proof{
  position:sticky;top:24px;
  display:grid;gap:12px;
}
.pw47-proof__brand{
  text-align:center;
  padding:20px;
  border-radius:var(--g-radius-md) var(--g-radius-md) 0 0;
  background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.018));
  border:1px solid var(--g-gold-border);
  border-bottom:none;
}
.pw47-proof__brand b{
  display:block;
  font-size:36px;font-weight:900;
  letter-spacing:.28em;
  color:var(--g-gold-light);
  font-family:Georgia,serif;
  line-height:1;
}
.pw47-proof__brand span{
  display:block;
  font-size:12px;
  letter-spacing:.24em;
  color:var(--g-gold);
  margin-top:6px;
  text-transform:uppercase;
  font-weight:900;
}
.pw47-proof__video{
  position:relative;
  aspect-ratio:16/9;
  margin-top:-12px;
  border-radius:14px;
  overflow:hidden;
  border:1px solid var(--g-gold-border);
  background:#030407;
}
.pw47-proof__video video{
  width:100%;height:100%;
  object-fit:cover;
  filter:saturate(.9) brightness(.7);
}
.pw47-proof__video-overlay{
  position:absolute;bottom:0;left:0;right:0;
  padding:8px 12px;
  background:linear-gradient(transparent,rgba(0,0,0,.7));
  font-size:10px;font-weight:800;
  letter-spacing:.08em;text-transform:uppercase;
  color:rgba(255,255,255,.5);
}
.pw47-proof__unlocks{
  padding:16px;
  border-radius:var(--g-radius-sm);
  border:1px solid var(--g-border);
  background:var(--g-surface);
}
.pw47-proof__unlocks>b{
  display:block;font-size:13px;color:#FFF5DC;margin-bottom:10px;
}
.pw47-proof__chips{
  display:grid;grid-template-columns:1fr 1fr;gap:6px;
}
.pw47-proof__chips span{
  padding:8px 10px;
  border-radius:10px;
  background:rgba(201,145,61,.07);
  border:1px solid rgba(201,145,61,.13);
  font-size:11px;font-weight:800;
  color:rgba(224,192,116,.85);
  text-align:center;
}
.pw47-proof__benefits{
  display:grid;gap:8px;
}
.pw47-proof__benefit{
  display:grid;grid-template-columns:auto 1fr;gap:6px 12px;
  padding:13px;
  border-radius:var(--g-radius-sm);
  border:1px solid var(--g-border);
  background:var(--g-surface);
}
.pw47-proof__benefit-icon{
  grid-row:span 2;
  color:var(--g-gold);
  padding-top:1px;
}
.pw47-proof__benefit b{
  font-size:13px;color:#FFF5DC;display:block;
}
.pw47-proof__benefit p{
  font-size:12px;color:var(--g-text-muted);margin:0;line-height:1.4;
}
.pw47-proof__lock{
  display:flex;align-items:center;gap:9px;
  font-size:12px;color:var(--g-text-muted);
  padding:12px 14px;
  border-radius:10px;
  background:rgba(255,255,255,.025);
  border:1px solid var(--g-border);
}
.pw47-proof__lock svg{color:var(--g-gold);flex:0 0 auto}

/* compare table */
.pw47-proof__compare{
  padding:16px;
  border-radius:var(--g-radius-sm);
  border:1px solid var(--g-border);
  background:var(--g-surface);
}
.pw47-proof__compare>b{
  display:block;font-size:13px;color:#FFF5DC;margin-bottom:12px;
}
.pw47-proof__compare table{
  width:100%;
  border-collapse:collapse;
  font-size:12px;
}
.pw47-proof__compare tbody tr{
  border-bottom:1px solid rgba(255,255,255,.05);
}
.pw47-proof__compare td{
  padding:7px 4px;
  color:var(--g-text-muted);
  vertical-align:middle;
}
.pw47-proof__compare td:nth-child(2),
.pw47-proof__compare td:nth-child(3){
  text-align:center;
  width:44px;
}
.pw47-proof__compare tfoot td{
  padding-top:10px;
  font-size:11px;font-weight:900;
  letter-spacing:.06em;
  color:var(--g-text-subtle);
  text-align:center;
}
.pw47-compare__pro-col{color:var(--g-gold)!important}
.pw47-check--yes{color:var(--g-gold)!important;display:inline-block;vertical-align:middle}
.pw47-check--no{color:var(--g-text-subtle);font-size:14px}

/* ─── PAYWALL RESPONSIVE ──────────────────────────────────────────────────── */
@media(max-width:1100px){
  .pw47-layout{grid-template-columns:1fr}
  .pw47-proof{position:relative;top:0}
