  display:grid;
  gap:12px;
  align-content:start;
  border:1px solid rgba(212,168,67,.18);
  background:rgba(255,255,255,.035);
  border-radius:18px;
  padding:16px;
}
.shareControls b{
  color:var(--mtc-text-primary,#f8fafc);
  font-size:14px;
}
.shareControls label{
  display:flex;
  align-items:center;
  gap:9px;
  color:var(--mtc-text-readable,#dbe4f0);
  font-size:13px;
  font-weight:800;
}
.shareControls input{
  width:17px;
  height:17px;
  accent-color:#d4a843;
}
.shareControls span,
.shareControls small,
.shareHint{
  color:var(--mtc-text-secondary,#cbd5e1);
  line-height:1.45;
  font-size:12px;
}
.shareError{
  color:#fecdd3;
  border:1px solid rgba(244,63,94,.25);
  background:rgba(244,63,94,.08);
  border-radius:12px;
  padding:10px;
  margin:0;
  font-size:12px;
}
.storyPreviewFrame{
  display:grid;
  place-items:center;
  min-height:560px;
  border:1px solid rgba(212,168,67,.18);
  background:radial-gradient(circle at top,rgba(212,168,67,.12),transparent 42%),rgba(0,0,0,.22);
  border-radius:22px;
  padding:18px;
  overflow:auto;
}
.storyPreviewFrame img{
  display:block;
  width:min(315px,100%);
  aspect-ratio:9/16;
  object-fit:contain;
  border-radius:18px;
  box-shadow:0 24px 80px rgba(0,0,0,.42),0 0 0 1px rgba(212,168,67,.22);
}
.storyPreviewSkeleton{
  width:min(315px,100%);
  aspect-ratio:9/16;
  display:grid;
  place-items:center;
  border-radius:18px;
  border:1px dashed rgba(212,168,67,.25);
  color:var(--mtc-text-secondary,#cbd5e1);
  background:rgba(255,255,255,.035);
  font-weight:800;
}
html[data-theme="light"] body:not(:has(.paywallFunnel)) .app .shareReviewButton{
  background:#fff8eb!important;
