/* Animated image product demo: no video, real screenshots only */
.animatedProductDemo{
  position:relative;
  width:100%;
  isolation:isolate;
  border-radius:inherit;
}
.animatedProductGlow{
  position:absolute;
  inset:8% 4% -6%;
  z-index:0;
  pointer-events:none;
  background:
    radial-gradient(circle at 24% 18%,rgba(240,197,90,.18),transparent 28%),
    radial-gradient(circle at 78% 72%,rgba(25,209,138,.10),transparent 30%);
  filter:blur(26px);
  opacity:.62;
  animation:productGlowDrift 8s ease-in-out infinite alternate;
}
.animatedProductStage{
  position:relative;
  z-index:1;
  overflow:hidden;
  border-radius:inherit;
  background:#04070b;
}
.animatedProductStage img,
.animatedProductStage video{
  display:block;
  width:100%;
  height:auto;
  object-fit:cover;
  object-position:center;
  transform:scale(1) translate3d(0,0,0);
  animation:productStillLoop 14s ease-in-out infinite alternate;
  will-change:transform;
}
.animatedProductStage video{
  aspect-ratio:16/9;
  background:#04070b;
  pointer-events:none;
}
.animatedProductFallback{
  display:none!important;
}
.animatedProductStage img+img{
  position:absolute;
  inset:0;
  opacity:0;
  animation:productFrameFade 18s ease-in-out infinite;
  animation-delay:calc(var(--frame-index) * 5s);
}
.animatedProductDemo.paywall .animatedProductGlow{
  inset:10% 2% -10%;
  opacity:.55;
}
.finalLandingVisual .animatedProductDemo,
.finalLandingVisual .animatedProductStage,
.finalLandingVisual .animatedProductStage img,
.finalLandingVisual .animatedProductStage video{
  height:100%!important;
}
.finalLandingVisual .animatedProductStage img,
.finalLandingVisual .animatedProductStage video{
  min-height:clamp(500px,50vw,720px)!important;
}
.finalPaywallImage.animatedProductDemo{
  display:block!important;
  border-radius:24px!important;
  border:1px solid rgba(240,197,90,.22)!important;
  box-shadow:0 28px 80px rgba(0,0,0,.54)!important;
  background:#04070b!important;
}
.finalPaywallImage .animatedProductStage img,
.finalPaywallImage .animatedProductStage video{
  height:auto!important;
  max-height:none!important;
  object-fit:cover!important;
}
.finalDemoImageCard{
  transition:transform .22s ease,border-color .22s ease,box-shadow .22s ease;
}
.finalDemoImageCard:hover{
  transform:translateY(-3px);
  border-color:rgba(240,197,90,.24)!important;
  box-shadow:0 26px 80px rgba(0,0,0,.34),0 0 0 1px rgba(240,197,90,.08) inset!important;
}
.finalDemoImageButton img{
  transition:transform .7s ease,filter .7s ease;
}
.finalDemoImageButton:hover img{
  transform:scale(1.018);
  filter:saturate(1.04) contrast(1.03);
}
@keyframes productStillLoop{
  0%{transform:scale(1) translate3d(0,0,0)}
  50%{transform:scale(1.018) translate3d(-.4%,.25%,0)}
  100%{transform:scale(1.035) translate3d(.55%,-.35%,0)}
}
@keyframes productGlowDrift{
  0%{opacity:.46;transform:translate3d(-1%,0,0) scale(.98)}
  100%{opacity:.68;transform:translate3d(1.2%,-1%,0) scale(1.02)}
}
@keyframes productFrameFade{
  0%,100%{opacity:0}
  12%,42%{opacity:1}
  54%{opacity:0}
}
