  font-weight:700;
  color:var(--analytics-text);
  overflow-wrap:anywhere;
}
.analyticsCommandSummaryRow>small{
  font-size:11px;
  color:var(--analytics-body);
  line-height:1.25;
}
.analyticsCommandSummaryRow.positive>b{color:#86efac}
.analyticsCommandSummaryRow.negative>b{color:#fca5a5}
.analyticsCommandSummaryRow.neutral>b{font-size:12px;font-weight:650;color:var(--analytics-body)}
.analyticsCommandHeroFoot{
  display:flex;
  align-items:center;
  gap:10px;
  margin-top:12px;
  padding-top:10px;
  border-top:1px solid rgba(255,255,255,.06);
  flex-wrap:wrap;
}
.analyticsCommandProgress{
  flex:1;
  min-width:120px;
  max-width:280px;
}
.analyticsCommandProgress .analyticsEdgeProgressBar{
  height:4px;
  border-radius:999px;
  background:rgba(255,255,255,.08);
}
.analyticsCommandProgress .analyticsEdgeProgressBar>span{
  background:linear-gradient(90deg,#3b82f6,#60a5fa);
}
.analyticsCommandSample{
  color:var(--analytics-body)!important;
  font-size:12px;
  font-weight:600;
  line-height:1.3;
  font-style:normal;
}
.analyticsCommandHeroFoot .analyticsConfidenceBadge{margin-left:auto}

/* ── 2. DECISION STRIP ── */
.analyticsDecisionStrip{padding:0}
.analyticsDecisionGrid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px;
}
.analyticsDecisionCard{
  padding:12px 14px;
  border-radius:13px;
  border:1px solid var(--analytics-border);
  background:var(--analytics-card);
  display:flex;
  flex-direction:column;
  gap:4px;
  min-height:104px;
  min-width:0;
  border-left:3px solid rgba(255,255,255,.12);
}
.analyticsDecisionCard.positive{
  border-left-color:rgba(34,197,94,.65);
  background:rgba(34,197,94,.05);
  border-color:rgba(34,197,94,.18);
}
.analyticsDecisionCard.negative{
  border-left-color:rgba(239,68,68,.60);
  background:rgba(239,68,68,.04);
  border-color:rgba(239,68,68,.16);
}
.analyticsDecisionCard.warn{
  border-left-color:rgba(251,191,36,.60);
  background:rgba(251,191,36,.04);
  border-color:rgba(251,191,36,.16);
}
.analyticsDecisionCard.neutral{border-left-color:rgba(168,180,200,.35)}
.analyticsDecisionLabel{
  color:var(--analytics-text-label);
  font-size:10px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.09em;
}
.analyticsDecisionAction{
  font-size:clamp(15px,1.6vw,17px);
  line-height:1.2;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  color:var(--analytics-text);
  font-weight:800;
  letter-spacing:-.015em;
}
.analyticsDecisionData{
  color:var(--analytics-body)!important;
  font-size:12px;
  line-height:1.35;
  font-weight:600;
}
.analyticsDecisionVerdict{
  display:inline-flex;
  align-self:flex-start;
  align-items:center;
  padding:3px 8px;
  border-radius:999px;
  font-style:normal;
  font-size:9px;
  font-weight:800;
  letter-spacing:.04em;
  text-transform:uppercase;
  border:1px solid rgba(255,255,255,.10);
  background:rgba(255,255,255,.04);
  margin-top:auto;
}
.analyticsDecisionVerdict.positive{color:#4ade80;border-color:rgba(34,197,94,.22);background:rgba(34,197,94,.08)}
.analyticsDecisionVerdict.negative{color:#f87171;border-color:rgba(239,68,68,.20);background:rgba(239,68,68,.07)}
.analyticsDecisionVerdict.warn{color:#fbbf24;border-color:rgba(251,191,36,.22);background:rgba(251,191,36,.08)}
.analyticsDecisionVerdict.neutral{color:var(--analytics-muted)}

/* ── 3. SYSTEM HEALTH ── */
.analyticsSystemHealth{padding:0}
.analyticsSystemHealthGrid{
  display:grid;
  grid-template-columns:minmax(150px,1.35fr) repeat(3,1fr);
  grid-template-rows:auto auto;
  gap:8px;
  align-items:stretch;
}
.analyticsSystemHealthGrid .analyticsKpiCard.health{
  grid-row:1/3;
  grid-column:1;
  min-height:148px;
  padding:14px 16px 12px;
  border-radius:14px;
  background:linear-gradient(160deg,rgba(12,14,20,.96),rgba(18,22,32,.92))!important;
  border:1px solid rgba(212,166,58,.20)!important;
  box-shadow:inset 0 1px 0 rgba(212,166,58,.06)!important;
  display:flex;
  flex-direction:column;
  justify-content:center;
}
.analyticsSystemHealthGrid .analyticsKpiCard.health:before,
.analyticsSystemHealthGrid .analyticsKpiCard.health:after{display:none!important}
.analyticsSystemHealthGrid .analyticsKpiCard.health.positive{
  border-color:rgba(212,166,58,.22)!important;
  box-shadow:inset 0 0 0 1px rgba(34,197,94,.10),inset 0 1px 0 rgba(212,166,58,.06)!important;
}
.analyticsSystemHealthGrid .analyticsKpiCard.health.negative{
  border-color:rgba(212,166,58,.16)!important;
  box-shadow:inset 0 0 0 1px rgba(239,68,68,.08)!important;
}
.analyticsSystemHealthGrid .analyticsKpiCard.health .analyticsKpiCardTop span{
  color:rgba(212,166,58,.80);
  font-size:9px;
  letter-spacing:.1em;
}
.analyticsSystemHealthGrid .analyticsKpiCard.health .analyticsKpiValue{
  font-size:clamp(30px,3.2vw,38px);
  letter-spacing:-.03em;
  font-weight:800;
}
.analyticsSystemHealthGrid .analyticsKpiCard.health .analyticsKpiSub{
  font-size:12px;
  font-weight:650;
  color:var(--analytics-body)!important;
}
.analyticsSystemHealthGrid .analyticsKpiCard.health.positive .analyticsKpiSub{color:#86efac!important}
.analyticsSystemHealthGrid .analyticsKpiCard.health .analyticsKpiHint{
  font-size:10px;
  color:var(--analytics-muted)!important;
  margin-top:2px;
}
.analyticsSystemHealthGrid .analyticsKpiCard.compact{
  min-height:68px;
  padding:9px 11px 8px;
  border-radius:12px;
  background:var(--analytics-card)!important;
  border:1px solid var(--analytics-border)!important;
  box-shadow:none!important;
}
.analyticsSystemHealthGrid .analyticsKpiCard.compact:before{display:none!important}
.analyticsSystemHealthGrid .analyticsKpiCard.compact .analyticsKpiValue{
  font-size:clamp(17px,1.8vw,21px);
  font-weight:750;
  color:var(--analytics-text);
}
.analyticsSystemHealthGrid .analyticsKpiCard.compact .analyticsKpiSub{
  font-size:11px;
  color:var(--analytics-body)!important;
  font-weight:600;
  line-height:1.25;
}
.analyticsSystemHealthGrid .analyticsKpiCard.compact .analyticsKpiCardTop span{
  font-size:9px;
  color:var(--analytics-text-label)!important;
}
.analyticsSystemHealthGrid .analyticsKpiCard.compact .analyticsKpiHint{
  font-size:9px;
  color:var(--analytics-muted)!important;
}

/* ── 4. EVIDENCE / AUDIT ── */
.analyticsEvidenceAudit{
  display:flex;
  flex-direction:column;
  gap:10px;
  padding-top:4px;
  opacity:.94;
}
.analyticsEvidenceHead{
  display:flex;
  align-items:baseline;
  justify-content:space-between;
  gap:8px;
  padding:0 2px;
}
.analyticsEvidenceHead h3{
  margin:0;
  font-size:13px;
  font-weight:700;
  color:var(--analytics-muted);
  letter-spacing:.02em;
  text-transform:uppercase;
}
.analyticsEvidenceHead span{
  font-size:11px;
  color:var(--analytics-muted);
}
.analyticsEvidenceAudit .analyticsBreakdownGrid{
  grid-template-columns:1.75fr 1fr;
  gap:10px;
}
.analyticsEvidenceAudit .card h3{
  font-size:14px!important;
}
.analyticsEvidenceAudit .cardHead p{
  font-size:11px!important;
  color:var(--analytics-muted)!important;
}
.analyticsSessionSingle.compact{
  padding:10px 12px;
  border-radius:11px;
  border:1px solid rgba(251,191,36,.16);
  background:rgba(251,191,36,.04);
  max-height:none;
  height:auto;
}
.analyticsSessionSingle.compact b{
  display:block;
  font-size:13px;
  margin-bottom:4px;
  color:var(--analytics-text);
}
.analyticsSessionSingle.compact .analyticsSessionMeta{
  display:block;
  margin:0 0 6px;
  color:var(--analytics-body)!important;
  font-size:12px;
  font-weight:600;
}
.analyticsSessionSingle.compact p{
  margin:0;
  color:var(--analytics-muted)!important;
  font-size:11px;
  line-height:1.4;
}
.analyticsSessionLeader.compact.observation{
  border-color:rgba(251,191,36,.20)!important;
  background:rgba(251,191,36,.05)!important;
}
.analyticsSessionLeader.compact.observation svg{color:#fbbf24}
.analyticsBehaviorCard.executive .cardBody{padding:12px 14px}
.analyticsBehaviorBandScore b{font-size:26px}
.analyticsBehaviorReading{font-size:13px;color:var(--analytics-body)!important}
.analyticsChartsSection.audit{
  opacity:.90;
  margin-top:0;
}
.analyticsChartsSection.audit .analyticsSectionHead.audit h3{
  font-size:12px;
  text-transform:uppercase;
  letter-spacing:.04em;
}

/* Light mode */
html[data-theme="light"] .analyticsPage{
  --analytics-text:#0f172a;
  --analytics-body:#334155;
  --analytics-muted:#64748b;
  --analytics-border:rgba(15,17,23,.10);
  --analytics-card:rgba(255,255,255,.94);
  --analytics-text-body:var(--analytics-body);
  --analytics-text-muted:var(--analytics-muted);
  --analytics-text-label:#475569;
}
html[data-theme="light"] .analyticsCommandHero{
  background:linear-gradient(155deg,rgba(255,253,248,.98),rgba(247,242,233,.94))!important;
  border-color:rgba(184,132,23,.16)!important;
  box-shadow:0 12px 36px rgba(78,58,22,.08)!important;
}
html[data-theme="light"] .analyticsCommandHeadline{color:#0f172a!important}
html[data-theme="light"] .analyticsCommandHeroSummary{background:rgba(248,250,252,.92)!important;border-color:rgba(15,17,23,.08)!important}
html[data-theme="light"] .analyticsCommandSummaryRow.positive>b{color:#15803d!important}
html[data-theme="light"] .analyticsCommandSummaryRow.negative>b{color:#b91c1c!important}
html[data-theme="light"] .analyticsDecisionCard{background:var(--analytics-card)!important;border-color:rgba(15,17,23,.10)!important}
html[data-theme="light"] .analyticsDecisionCard.positive{background:rgba(240,253,244,.92)!important}
html[data-theme="light"] .analyticsDecisionCard.negative{background:rgba(255,241,242,.92)!important}
html[data-theme="light"] .analyticsDecisionCard.warn{background:rgba(255,251,235,.92)!important}
html[data-theme="light"] .analyticsSystemHealthGrid .analyticsKpiCard.health{
  background:linear-gradient(160deg,rgba(255,253,248,.98),rgba(247,242,233,.92))!important;
  border-color:rgba(184,132,23,.18)!important;
}
html[data-theme="light"] .analyticsSystemHealthGrid .analyticsKpiCard.health.positive .analyticsKpiSub{color:#15803d!important}
html[data-theme="light"] .analyticsSystemHealthGrid .analyticsKpiCard.compact{background:var(--analytics-card)!important}

/* Responsive */
@media(max-width:1180px){
  .analyticsCommandHeroMain{grid-template-columns:100px minmax(0,1fr);gap:16px}
  .analyticsCommandHeroSummary{grid-column:span 2}
  .analyticsSystemHealthGrid{grid-template-columns:1.2fr repeat(2,1fr)}
  .analyticsSystemHealthGrid .analyticsKpiCard.health{grid-row:1/3;grid-column:1}
  .analyticsEvidenceAudit .analyticsBreakdownGrid{grid-template-columns:1fr}
}
@media(max-width:860px){
  .analyticsCommandHeroMain{grid-template-columns:1fr;gap:14px}
  .analyticsCommandHeroScore{flex-direction:row;align-items:center;gap:12px}
  .analyticsCommandHeroSummary{grid-column:span 1}
  .analyticsDecisionGrid{grid-template-columns:1fr}
  .analyticsSystemHealthGrid{grid-template-columns:repeat(2,1fr)}
  .analyticsSystemHealthGrid .analyticsKpiCard.health{grid-row:span 1;grid-column:span 2;min-height:88px}
  .analyticsBehaviorSignals.tight{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:390px){
  .analyticsPage{gap:12px;padding-bottom:calc(96px + env(safe-area-inset-bottom))}
  .analyticsCommandHero{padding:14px 14px 12px}
  .analyticsCommandHeroMain{grid-template-columns:1fr;gap:12px}
  .analyticsCommandHeroScore{align-items:flex-start}
  .analyticsEdgeScoreRing.command{width:88px;height:88px}
  .analyticsEdgeScoreRing.command .analyticsEdgeScoreValue{font-size:34px}
  .analyticsCommandHeadline{font-size:17px;line-height:1.4}
  .analyticsCommandHeroFoot{flex-direction:column;align-items:flex-start;gap:6px}
  .analyticsCommandHeroFoot .analyticsConfidenceBadge{margin-left:0}
  .analyticsDecisionGrid,.analyticsSystemHealthGrid,.analyticsBehaviorSignals.tight{grid-template-columns:1fr}
  .analyticsSystemHealthGrid .analyticsKpiCard.health{grid-column:span 1;min-height:80px}
  .analyticsDecisionCard{min-height:92px}
  .analyticsBehaviorFocus.tight{grid-template-columns:1fr}
  .analyticsBreakdownGrid,.analyticsBreakdownGrid.sessionCompact{grid-template-columns:1fr}
}

/* ═══ Analytics Pass 2 — Premium polish ═══ */

/* Filtros compactos */
.analyticsPage .analyticsFiltersBar{
  padding:8px 12px;
  gap:6px;
  border-radius:12px;
}
.analyticsPage .analyticsFiltersLabel{
  font-size:11px;
  gap:6px;
}
.analyticsPage .analyticsFiltersGrid{
  gap:6px;
  grid-template-columns:repeat(auto-fit,minmax(118px,1fr));
}
.analyticsPage .analyticsFilterField{gap:3px}
.analyticsPage .analyticsFilterField>span{font-size:10px}
.analyticsPage .analyticsFilterField .input.small{
  min-height:32px;
  padding:5px 8px;
  font-size:12px;
}

/* Setup ranking visual */
.analyticsSetupRankList{
  display:flex;
  flex-direction:column;
  gap:6px;
}
.analyticsSetupRank{
  display:grid;
  grid-template-columns:minmax(0,1.35fr) minmax(80px,1fr) minmax(88px,auto);
  gap:10px;
  align-items:center;
  padding:10px 12px;
  border-radius:11px;
  border:1px solid var(--analytics-border);
  background:var(--analytics-card);
  min-width:0;
}
.analyticsSetupRank.validated{
  border-color:rgba(34,197,94,.18);
  background:rgba(34,197,94,.04);
}
.analyticsSetupRank.observation{
  border-color:rgba(251,191,36,.14);
  background:rgba(251,191,36,.03);
}
.analyticsSetupRank.insufficient,
.analyticsSetupRank.lowSample{
  opacity:.58;
  border-color:rgba(255,255,255,.06);
  background:rgba(255,255,255,.015);
}
.analyticsSetupRank.leader{
  border-color:rgba(34,197,94,.24);
  background:rgba(34,197,94,.06);
  opacity:1;
  box-shadow:inset 0 0 0 1px rgba(34,197,94,.08);
}
.analyticsSetupRankLeft{min-width:0}
.analyticsSetupRankName{
  display:block;
  font-size:13px;
  line-height:1.25;
  color:var(--analytics-text);
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.analyticsSetupRankSub{
  display:block;
  margin-top:3px;
  font-size:11px;
  line-height:1.3;
  color:var(--analytics-body)!important;
  font-weight:600;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.analyticsSetupRank.lowSample .analyticsSetupRankName,
.analyticsSetupRank.lowSample .analyticsSetupRankSub{color:var(--analytics-muted)!important}
.analyticsSetupRankCenter{min-width:0;padding:0 2px}
.analyticsSetupStrengthBar.rank{
  height:5px;
  border-radius:999px;
  background:rgba(255,255,255,.07);
  overflow:hidden;
}
.analyticsSetupStrengthBar.rank>span{
  display:block;
  height:100%;
  border-radius:999px;
  transition:width .25s ease;
}
.analyticsSetupRankRight{
  display:flex;
  flex-direction:column;
  align-items:flex-end;
  gap:4px;
  min-width:0;
}
.analyticsSetupPfMini{
  font-size:10px;
  font-weight:700;
  color:var(--analytics-body);
  line-height:1.2;
  text-align:right;
}
.analyticsSetupPfMini.weak{color:var(--analytics-muted)}
.analyticsSetupPfMini.weak em{
  display:block;
  font-style:normal;
  font-size:9px;
  font-weight:650;
  color:rgba(251,191,36,.85);
  margin-top:1px;
}
.analyticsSetupPfMini.muted{
  font-size:9px;
  color:var(--analytics-muted);
  font-weight:600;
}

/* Auditoría compacta */
.analyticsChartsSection.audit.compact{opacity:.86;margin-top:0}
.analyticsChartsGrid.audit.compact{
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:8px;
}
.analyticsChartCard.audit.primary .cardBody{padding:10px 12px 8px}
.analyticsChartCard.audit.secondary .cardBody{padding:8px 10px 6px}
.analyticsChartCard.audit .cardHead h3{font-size:13px}
.analyticsChartCard.audit .cardHead p{font-size:10px}
.analyticsChartBody.audit.compact{padding-top:0}
.analyticsPatternCompact{
  padding:8px 10px;
  border-radius:10px;
  border:1px solid rgba(255,255,255,.07);
  background:rgba(255,255,255,.02);
}
.analyticsPatternCompact>b{
  display:block;
  font-size:13px;
  line-height:1.25;
  color:var(--analytics-text);
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.analyticsPatternCompactMeta{
  display:flex;
  flex-wrap:wrap;
  gap:6px;
  margin-top:6px;
  align-items:center;
}
.analyticsPatternCompactMeta strong{font-size:15px}
.analyticsPatternCompactMeta span{
  font-size:10px;
  color:var(--analytics-muted);
