}
.analyticsPatternCompact.inline b{font-size:16px}
.analyticsPatternCompact.inline span{font-size:11px;color:var(--analytics-muted)}
.analyticsPatternCompact.empty{
  padding:10px 12px;
  border-style:dashed;
