html[data-theme="light"] .analyticsSetupRank{background:var(--analytics-card)!important;border-color:rgba(15,17,23,.10)!important}
html[data-theme="light"] .analyticsSetupRank.validated{background:rgba(240,253,244,.92)!important}
html[data-theme="light"] .analyticsSetupRank.observation{background:rgba(255,251,235,.88)!important}
