}
.analyticsSetupRankCard.validated{
  border-color:rgba(34,197,94,.20);
  background:rgba(34,197,94,.05);
}
.analyticsSetupRankCard.observation{
  border-color:rgba(251,191,36,.16);
  background:rgba(251,191,36,.04);
