  border-radius:10px;
  border:1px solid rgba(251,191,36,.14);
  background:rgba(251,191,36,.03);
}
.analyticsShell .analyticsSessionSingle.compact b{
  display:block;
  font-size:12px;
  margin-bottom:3px;
  color:var(--ax-text);
}
.analyticsShell .analyticsSessionSingle.compact .analyticsSessionMeta{
  display:block;
  margin:0 0 5px;
  color:var(--ax-body)!important;
  font-size:11px;
  font-weight:600;
}
.analyticsShell .analyticsSessionSingle.compact p{
  margin:0;
  color:var(--ax-muted)!important;
  font-size:10px;
  line-height:1.4;
}
.analyticsShell .analyticsSessionGrid{gap:6px}
.analyticsShell .analyticsSessionCard.compact{padding:8px 9px;border-radius:10px}
.analyticsShell .analyticsSessionCard.compact>b{font-size:16px}

/* ── BEHAVIOR COMPACT ── */
.analyticsShell .analyticsBehaviorCompact .cardHead{margin-bottom:6px}
.analyticsShell .analyticsBehaviorCompactBody{
  display:flex;
  flex-direction:column;
  gap:7px;
}
.analyticsShell .analyticsBehaviorCompactScore{
  display:grid;
  grid-template-columns:auto 1fr;
  gap:8px;
  align-items:center;
  padding:8px 10px;
  border-radius:10px;
  border:1px solid var(--ax-border);
  background:var(--ax-surface);
}
.analyticsShell .analyticsBehaviorCompactScore.positive{border-color:rgba(34,197,94,.16);background:rgba(34,197,94,.04)}
.analyticsShell .analyticsBehaviorCompactScore.negative{border-color:rgba(239,68,68,.14);background:rgba(239,68,68,.04)}
.analyticsShell .analyticsBehaviorCompactScoreVal{
  display:flex;
  align-items:baseline;
  gap:2px;
}
.analyticsShell .analyticsBehaviorCompactScoreVal b{font-size:22px;line-height:1;color:var(--ax-text)}
.analyticsShell .analyticsBehaviorCompactScoreVal em{font-style:normal;font-size:11px;color:var(--ax-muted)}
.analyticsShell .analyticsBehaviorCompactHeadline{
  margin:0;
  font-size:12px;
  line-height:1.35;
  font-weight:600;
  color:var(--ax-body);
}
.analyticsShell .analyticsBehaviorCompactFocus{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:6px;
}
.analyticsShell .analyticsBehaviorCompactFocusItem{
  display:flex;
  align-items:flex-start;
  gap:6px;
  padding:7px 8px;
  border-radius:9px;
  border:1px solid var(--ax-border);
  background:var(--ax-surface);
  min-width:0;
}
.analyticsShell .analyticsBehaviorCompactFocusItem.positive{border-color:rgba(34,197,94,.14);background:rgba(34,197,94,.03)}
.analyticsShell .analyticsBehaviorCompactFocusItem.negative{border-color:rgba(239,68,68,.12);background:rgba(239,68,68,.03)}
.analyticsShell .analyticsBehaviorCompactFocusItem span{
  display:block;
  font-size:8px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.07em;
  color:var(--ax-muted);
}
.analyticsShell .analyticsBehaviorCompactFocusItem b{
  display:block;
  margin-top:2px;
  font-size:11px;
  line-height:1.2;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.analyticsShell .analyticsBehaviorCompactMetrics{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:5px;
}
.analyticsShell .analyticsBehaviorCompactMetric{
  display:flex;
  align-items:center;
  gap:5px;
  padding:6px 7px;
  border-radius:8px;
  border:1px solid rgba(255,255,255,.06);
  background:rgba(255,255,255,.015);
}
.analyticsShell .analyticsBehaviorCompactMetric span{display:block;font-size:8px;color:var(--ax-muted)}
.analyticsShell .analyticsBehaviorCompactMetric b{display:block;margin-top:1px;font-size:12px;color:var(--ax-text)}

/* ── AUDIT CHARTS ── */
.analyticsShell .analyticsAuditSection{
  display:flex;
  flex-direction:column;
  gap:6px;
  opacity:.88;
  margin-top:2px;
}
.analyticsShell .analyticsAuditHead{
  display:flex;
  align-items:baseline;
  justify-content:space-between;
  gap:8px;
}
.analyticsShell .analyticsAuditHead h3{
  margin:0;
  font-size:11px;
  font-weight:700;
  color:var(--ax-muted);
  text-transform:uppercase;
  letter-spacing:.05em;
}
.analyticsShell .analyticsAuditHead span{font-size:10px;color:var(--ax-muted)}
.analyticsShell .analyticsAuditGrid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:8px;
}
.analyticsShell .analyticsChartCard{
  min-width:0;
  max-height:300px;
  overflow:hidden;
  display:flex;
  flex-direction:column;
}
.analyticsShell .analyticsChartCard .cardHead{
  flex-shrink:0;
  margin-bottom:4px;
  padding-bottom:0;
}
.analyticsShell .analyticsChartCard .cardHead h3{font-size:12px!important}
.analyticsShell .analyticsChartCard .cardHead p{font-size:10px!important}
.analyticsShell .analyticsChartCardBody{
  flex:1;
  min-height:0;
  width:100%;
  display:flex;
  align-items:stretch;
}
.analyticsShell .analyticsChartCardBody .recharts-responsive-container,
.analyticsShell .analyticsChartCardBody>div{width:100%!important}
.analyticsShell .analyticsChartCardFallback{
  flex:1;
  min-height:160px;
  display:flex;
  align-items:center;
  justify-content:center;
}
.analyticsShell .analyticsPatternCompact{
  padding:8px 10px;
  border-radius:9px;
  border:1px solid rgba(255,255,255,.06);
  background:rgba(255,255,255,.015);
}
.analyticsShell .analyticsPatternCompact.empty{
  border-style:dashed;
  background:transparent;
}
.analyticsShell .analyticsPatternCompact.empty span{
  font-size:10px;
  color:var(--ax-muted);
  line-height:1.4;
}

/* ── EMPTY STATE ── */
.analyticsShell .analyticsEmptyPremium,
.analyticsShell .analyticsSectionEmpty{
  padding:18px 16px;
  border-radius:12px;
}

/* ── LIGHT MODE ── */
html[data-theme="light"] .analyticsShell.analyticsPage{
  --ax-text:#0f172a;
  --ax-body:#334155;
  --ax-muted:#64748b;
  --ax-label:#475569;
  --ax-border:rgba(15,17,23,.10);
  --ax-surface:rgba(255,255,255,.96);
}
html[data-theme="light"] .analyticsShell .analyticsTopBar{
  background:linear-gradient(180deg,rgba(255,253,248,.98),rgba(247,242,233,.94))!important;
  border-color:rgba(184,132,23,.14)!important;
}
html[data-theme="light"] .analyticsShell .analyticsTopBarBrand{color:#b8860b}
html[data-theme="light"] .analyticsShell .analyticsFiltersCompact{background:rgba(255,255,255,.96)!important}
html[data-theme="light"] .analyticsShell .analyticsHero{
  background:linear-gradient(155deg,rgba(255,253,248,.98),rgba(247,242,233,.94))!important;
  border-color:rgba(184,132,23,.14)!important;
  box-shadow:0 10px 32px rgba(78,58,22,.07)!important;
}
html[data-theme="light"] .analyticsShell .analyticsHeroHeadline{color:#0f172a!important}
html[data-theme="light"] .analyticsShell .analyticsHeroSummary{background:rgba(248,250,252,.92)!important}
html[data-theme="light"] .analyticsShell .analyticsHeroSummaryRow.positive>b{color:#15803d!important}
html[data-theme="light"] .analyticsShell .analyticsHeroSummaryRow.negative>b{color:#b91c1c!important}
html[data-theme="light"] .analyticsShell .analyticsActionCard{background:var(--ax-surface)!important}
html[data-theme="light"] .analyticsShell .analyticsActionCard.positive{background:rgba(240,253,244,.92)!important}
html[data-theme="light"] .analyticsShell .analyticsActionCard.negative{background:rgba(255,241,242,.92)!important}
html[data-theme="light"] .analyticsShell .analyticsActionCard.warn{background:rgba(255,251,235,.92)!important}
html[data-theme="light"] .analyticsShell .analyticsSystemHealthGrid .analyticsKpiCard.health{
  background:linear-gradient(160deg,rgba(255,253,248,.98),rgba(247,242,233,.92))!important;
  border-color:rgba(184,132,23,.16)!important;
}
html[data-theme="light"] .analyticsShell .analyticsSystemHealthGrid .analyticsKpiCard.health.positive .analyticsKpiSub{color:#15803d!important}
html[data-theme="light"] .analyticsShell .analyticsSetupRankCard.validated{background:rgba(240,253,244,.92)!important}
html[data-theme="light"] .analyticsShell .analyticsSetupRankCard.observation{background:rgba(255,251,235,.88)!important}
html[data-theme="light"] .analyticsShell .analyticsEdgeScoreRingInner{background:#f8fafc!important}

/* ── RESPONSIVE ── */
@media(max-width:1180px){
  .analyticsShell .analyticsHeroMain{grid-template-columns:88px minmax(0,1fr);gap:14px}
  .analyticsShell .analyticsHeroSummary{grid-column:span 2}
  .analyticsShell .analyticsSystemHealthGrid{grid-template-columns:1.15fr repeat(2,1fr)}
  .analyticsShell .analyticsSystemHealthGrid .analyticsKpiCard.health{grid-row:1/3;grid-column:1}
  .analyticsShell .analyticsEvidenceGrid{grid-template-columns:1fr}
  .analyticsShell .analyticsFiltersCompactGrid{grid-template-columns:repeat(3,minmax(0,1fr))}
}
@media(max-width:860px){
  .analyticsShell .analyticsHeroMain{grid-template-columns:1fr;gap:12px}
  .analyticsShell .analyticsHeroScore{flex-direction:row;align-items:center;gap:10px}
  .analyticsShell .analyticsHeroSummary{grid-column:span 1}
  .analyticsShell .analyticsActionBoardGrid{grid-template-columns:1fr}
  .analyticsShell .analyticsSystemHealthGrid{grid-template-columns:repeat(2,1fr)}
  .analyticsShell .analyticsSystemHealthGrid .analyticsKpiCard.health{grid-row:span 1;grid-column:span 2;min-height:80px}
  .analyticsShell .analyticsFiltersCompact{flex-direction:column;align-items:stretch}
  .analyticsShell .analyticsFiltersCompactLabel{border-right:none;padding-bottom:4px;border-bottom:1px solid rgba(255,255,255,.06)}
  .analyticsShell .analyticsFiltersCompactGrid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .analyticsShell .analyticsTopBar{flex-direction:column;align-items:flex-start;gap:8px}
}
@media(max-width:390px){
  .analyticsShell.analyticsPage{gap:8px;padding-bottom:calc(96px + env(safe-area-inset-bottom))}
  .analyticsShell .analyticsHero{padding:12px}
  .analyticsShell .analyticsHeroMain{grid-template-columns:1fr}
  .analyticsShell .analyticsHeroScore{align-items:flex-start}
  .analyticsShell .analyticsEdgeScoreRing.command{width:80px;height:80px}
  .analyticsShell .analyticsEdgeScoreRing.command .analyticsEdgeScoreValue{font-size:30px}
  .analyticsShell .analyticsHeroHeadline{font-size:15px}
  .analyticsShell .analyticsHeroFoot{flex-direction:column;align-items:flex-start}
  .analyticsShell .analyticsHeroFoot .analyticsConfidenceBadge{margin-left:0}
  .analyticsShell .analyticsActionBoardGrid,
  .analyticsShell .analyticsSystemHealthGrid,
  .analyticsShell .analyticsAuditGrid,
  .analyticsShell .analyticsBehaviorCompactFocus,
  .analyticsShell .analyticsFiltersCompactGrid{grid-template-columns:1fr}
  .analyticsShell .analyticsSystemHealthGrid .analyticsKpiCard.health{grid-column:span 1}
  .analyticsShell .analyticsSetupRankMeta{flex-direction:row;width:100%;justify-content:space-between}
}

/* ═══════════════════════════════════════════════════════════════
   ANALYTICS VALIDATION LAYER — mitad inferior premium
   ═══════════════════════════════════════════════════════════════ */

.analyticsShell .analyticsValidationSection{
  display:flex;
  flex-direction:column;
  gap:10px;
  margin-top:6px;
  padding-top:8px;
  border-top:1px solid rgba(255,255,255,.05);
}
.analyticsShell .analyticsValidationSectionHead h3{
  margin:0;
  font-size:14px;
  font-weight:750;
  color:var(--ax-text);
  letter-spacing:-.01em;
}
.analyticsShell .analyticsValidationSectionHead p{
  margin:3px 0 0;
  font-size:11px;
  color:var(--ax-muted);
  line-height:1.35;
}

/* Grid 7/5 — balanceado */
.analyticsShell .analyticsValidationGrid{
  display:grid;
  grid-template-columns:minmax(0,7fr) minmax(0,5fr);
  gap:10px;
  align-items:stretch;
}
.analyticsShell .analyticsValidationLeft,
.analyticsShell .analyticsValidationRight{
  display:flex;
  flex-direction:column;
  gap:8px;
  min-width:0;
}
.analyticsShell .analyticsValidationRight{
  justify-content:flex-start;
}

/* Edge en validación */
.analyticsShell .analyticsEdgeValidation{
  padding:10px 12px;
  border-radius:11px;
  border:1px solid rgba(255,255,255,.07);
  background:rgba(255,255,255,.02);
  min-width:0;
  flex:0 0 auto;
}
.analyticsShell .analyticsEdgeValidationHead h4{
  margin:0;
  font-size:13px;
  font-weight:750;
  color:var(--ax-text);
}
.analyticsShell .analyticsEdgeValidationHead p{
  margin:3px 0 0;
  font-size:10px;
  color:var(--ax-muted);
}
.analyticsShell .analyticsEdgeValidationBody{
  display:flex;
  flex-direction:column;
  gap:8px;
  margin-top:8px;
}
.analyticsShell .analyticsSetupGroupLabel{
  display:block;
  margin-bottom:6px;
  font-size:9px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.08em;
  color:var(--ax-muted);
}
.analyticsShell .analyticsSetupPrimaryList{
  display:flex;
  flex-direction:column;
  gap:6px;
}
.analyticsShell .analyticsSetupPrimaryList.compact{gap:5px}

/* Edge candidate — tesis operativa */
.analyticsShell .analyticsEdgeCandidate{
  padding:10px 12px;
  border-radius:10px;
  border:1px solid rgba(251,191,36,.16);
  background:linear-gradient(160deg,rgba(251,191,36,.05),rgba(255,255,255,.015));
}
.analyticsShell .analyticsEdgeCandidateHead{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  margin-bottom:5px;
}
.analyticsShell .analyticsEdgeCandidateLabel{
  font-size:9px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.08em;
  color:var(--ax-muted);
}
.analyticsShell .analyticsEdgeCandidateBadge{
  font-style:normal;
  font-size:8px;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:.04em;
  padding:2px 6px;
  border-radius:999px;
  color:#fbbf24;
  border:1px solid rgba(251,191,36,.18);
  background:rgba(251,191,36,.06);
}
.analyticsShell .analyticsEdgeCandidateName{
  display:block;
  font-size:15px;
  font-weight:800;
  color:var(--ax-text);
  line-height:1.2;
  letter-spacing:-.02em;
}
.analyticsShell .analyticsEdgeCandidateMetrics{
  margin:4px 0 0;
  font-size:11px;
  color:var(--ax-body);
  font-weight:600;
  line-height:1.4;
  overflow-wrap:anywhere;
}
.analyticsShell .analyticsEdgeCandidateReading{
  margin:6px 0 0;
  font-size:10px;
  color:var(--ax-muted);
  line-height:1.4;
}

/* Progreso a validación */
.analyticsShell .analyticsValidationProgress{
  display:flex;
  flex-direction:column;
  gap:3px;
  margin-top:8px;
}
.analyticsShell .analyticsValidationProgressBar{
  height:3px;
  border-radius:999px;
  background:rgba(255,255,255,.06);
  overflow:hidden;
}
.analyticsShell .analyticsValidationProgressBar>span{
  display:block;
  height:100%;
  border-radius:999px;
  background:linear-gradient(90deg,rgba(251,191,36,.55),rgba(251,191,36,.22));
  transition:width .25s ease;
}
.analyticsShell .analyticsValidationProgress small{
  font-size:9px;
  color:var(--ax-muted);
  font-weight:600;
}

/* Setup primary cards */
.analyticsShell .analyticsSetupPrimaryCard{
  padding:8px 10px;
  border-radius:9px;
  border:1px solid rgba(255,255,255,.05);
  background:rgba(255,255,255,.015);
}
.analyticsShell .analyticsSetupPrimaryCard.validated{
  border-color:rgba(34,197,94,.14);
  background:rgba(34,197,94,.03);
}
.analyticsShell .analyticsSetupPrimaryCard.observation{
  border-color:rgba(251,191,36,.12);
  background:rgba(251,191,36,.025);
}
.analyticsShell .analyticsSetupPrimaryHead{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  margin-bottom:8px;
}
.analyticsShell .analyticsSetupPrimaryName{
  font-size:13px;
  font-weight:750;
  color:var(--ax-text);
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  min-width:0;
}
.analyticsShell .analyticsSetupPrimaryBadge{
  flex-shrink:0;
  font-size:8px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.04em;
  padding:2px 6px;
  border-radius:999px;
}
.analyticsShell .analyticsSetupPrimaryBadge.validated{
  color:#4ade80;
  border:1px solid rgba(34,197,94,.22);
  background:rgba(34,197,94,.08);
}
.analyticsShell .analyticsSetupPrimaryBadge.observation{
  color:#fbbf24;
  border:1px solid rgba(251,191,36,.22);
  background:rgba(251,191,36,.08);
}
.analyticsShell .analyticsSetupMiniMetrics{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:6px;
}
.analyticsShell .analyticsSetupMiniMetric span{
  display:block;
  font-size:8px;
  color:var(--ax-muted);
  text-transform:uppercase;
  letter-spacing:.05em;
}
.analyticsShell .analyticsSetupMiniMetric b{
  display:block;
  margin-top:2px;
  font-size:12px;
  color:var(--ax-text);
  font-weight:700;
}
.analyticsShell .analyticsSetupPrimaryPf{
  display:block;
  margin-top:6px;
  font-size:10px;
  color:var(--ax-body);
}
.analyticsShell .analyticsSetupPrimaryPf.weak{color:var(--ax-muted)}

/* Muestra pendiente — cola de investigación */
.analyticsShell .analyticsPendingSetups{
  padding:9px 11px;
  border-radius:10px;
  border:1px solid rgba(255,255,255,.05);
  background:rgba(255,255,255,.012);
  flex:1 1 auto;
}
.analyticsShell .analyticsPendingSetupsHead b{
  display:block;
  font-size:11px;
  font-weight:750;
  color:var(--ax-body);
}
.analyticsShell .analyticsPendingSetupsHead span{
  display:block;
  margin-top:2px;
  font-size:10px;
  color:var(--ax-muted);
  line-height:1.35;
}
.analyticsShell .analyticsPendingSetupsGrid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:5px;
  margin-top:7px;
}
.analyticsShell .analyticsPendingSetupChip{
  display:flex;
  align-items:center;
  gap:6px;
  flex-wrap:wrap;
  padding:5px 8px;
  border-radius:7px;
  background:rgba(255,255,255,.02);
  min-width:0;
}
.analyticsShell .analyticsPendingSetupName{
  font-size:11px;
  color:var(--ax-text);
  font-weight:650;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  flex:1 1 auto;
  min-width:0;
}
.analyticsShell .analyticsPendingSetupCount{
  font-size:10px;
  color:var(--ax-muted);
  font-weight:700;
  flex-shrink:0;
}
.analyticsShell .analyticsPendingSetupPl{
  font-size:10px;
  font-weight:700;
  flex-shrink:0;
}

/* Cobertura de sesión */
.analyticsShell .analyticsCoverageCard{
  padding:9px 11px;
  border-radius:10px;
  border:1px solid rgba(255,255,255,.06);
  background:rgba(255,255,255,.02);
}
.analyticsShell .analyticsCoverageHead h4{
  margin:0;
  font-size:12px;
  font-weight:750;
  color:var(--ax-text);
}
.analyticsShell .analyticsCoverageHead p{
  margin:2px 0 0;
  font-size:10px;
  color:var(--ax-muted);
}
.analyticsShell .analyticsSessionConcentration{
  margin-top:7px;
  padding:8px 9px;
  border-radius:9px;
  border:1px solid rgba(255,255,255,.05);
  background:rgba(255,255,255,.015);
}
.analyticsShell .analyticsSessionConcentrationTop{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  margin-bottom:4px;
}
.analyticsShell .analyticsSessionConcentrationTop b{
  font-size:12px;
  color:var(--ax-text);
  font-weight:700;
}
.analyticsShell .analyticsCoverageBadge{
  font-style:normal;
  font-size:8px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.04em;
  padding:2px 6px;
  border-radius:999px;
}
.analyticsShell .analyticsCoverageBadge.warn{
  color:#fbbf24;
  border:1px solid rgba(251,191,36,.14);
  background:rgba(251,191,36,.05);
