  background:rgba(255,255,255,.05);
  overflow:hidden;
}
.analyticsShell .analyticsSessionConcentrationBar.inline{margin:4px 0}
.analyticsShell .analyticsSessionConcentrationBar>span{
  display:block;
  height:100%;
  border-radius:999px;
  background:linear-gradient(90deg,rgba(251,191,36,.40),rgba(251,191,36,.15));
}
.analyticsShell .analyticsSessionConcentrationData{
  display:block;
  font-size:11px;
  color:var(--ax-body);
  font-weight:600;
  margin-bottom:5px;
}
.analyticsShell .analyticsSessionConcentrationLabel{
  display:block;
  margin-top:3px;
  font-size:9px;
  color:var(--ax-muted);
  font-weight:600;
}
.analyticsShell .analyticsSessionConcentration p{
  margin:6px 0 0;
  font-size:10px;
  color:var(--ax-muted);
  line-height:1.4;
}
.analyticsShell .analyticsSessionDistribution{
  display:flex;
  flex-direction:column;
  gap:6px;
  margin-top:8px;
}
.analyticsShell .analyticsSessionDistRow{
  padding:7px 8px;
  border-radius:8px;
  border:1px solid rgba(255,255,255,.06);
  background:rgba(255,255,255,.015);
}
.analyticsShell .analyticsSessionDistTop{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
}
.analyticsShell .analyticsSessionDistTop span{
  font-size:11px;
  font-weight:700;
