/* ═══════════════════════════════════════════════════════════════
   TRADING INTELLIGENCE CENTER — Product Architecture v2
   ═══════════════════════════════════════════════════════════════ */

.analyticsIntelligenceCenter{
  --tic-bg:rgba(255,255,255,.02);
  --tic-border:rgba(255,255,255,.06);
  --tic-gold:rgba(212,166,58,.35);
  --tic-green:rgba(34,197,94,.18);
  --tic-red:rgba(239,68,68,.16);
  --tic-amber:rgba(251,191,36,.16);
  --tic-blue:rgba(96,165,250,.12);
  display:flex;
  flex-direction:column;
  gap:10px;
}

/* Intelligence Header refinements */
.analyticsIntelligenceCenter .analyticsTopBarReliability.good b{color:#4ade80}
.analyticsIntelligenceCenter .analyticsTopBarReliability.warn b{color:#fbbf24}
.analyticsIntelligenceCenter .analyticsTopBarReliability.neutral b{color:var(--ax-muted)}

/* Fold: Command + Directives + KPI */
.analyticsIntelligenceFold{
  display:flex;
  flex-direction:column;
  gap:8px;
}

/* ── 1. EXECUTIVE COMMAND ── */
.analyticsCommand{
  border-radius:12px;
  background:linear-gradient(135deg,rgba(255,255,255,.03),rgba(255,255,255,.01));
  border:1px solid var(--tic-border);
  padding:14px 16px;
}
.analyticsCommandMain{
  display:grid;
  grid-template-columns:auto 1fr auto;
  gap:14px 18px;
  align-items:start;
}
.analyticsCommandScore{display:flex;flex-direction:column;align-items:center;gap:4px;min-width:72px}
.analyticsCommandScoreRing{
  width:68px;height:68px;border-radius:50%;
  background:conic-gradient(var(--ring-color,#94a3b8) calc(var(--score-pct,0)*1%),rgba(255,255,255,.06) 0);
  display:grid;place-items:center;
}
.analyticsCommandScoreInner{
  width:54px;height:54px;border-radius:50%;
  background:rgba(8,10,14,.92);
  border:1px solid rgba(255,255,255,.06);
  display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1;
}
.analyticsCommandScoreInner b{font-size:18px;font-weight:800;color:var(--ax-text)}
.analyticsCommandScoreInner span{font-size:8px;color:var(--ax-muted)}
.analyticsCommandScore>em{font-size:8px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--ax-muted)}
.analyticsCommandNarrative{min-width:0}
.analyticsCommandEyebrow{
  display:block;font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;
  color:var(--ax-muted);margin-bottom:6px;
}
.analyticsCommandNarrative h2{
  margin:0;font-size:14px;font-weight:700;line-height:1.45;color:var(--ax-text);
  overflow-wrap:anywhere;word-break:break-word;
}
.analyticsCommandWeekly{margin:6px 0 0;font-size:11px;color:rgba(212,166,58,.85);line-height:1.4}
.analyticsCommandSub{margin:4px 0 0;font-size:10px;color:var(--ax-muted);line-height:1.4}
.analyticsCommandSignals{display:flex;flex-direction:column;gap:6px;min-width:140px}
.analyticsCommandSignal{
  padding:6px 8px;border-radius:8px;
  background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.04);
}
.analyticsCommandSignal>span{display:block;font-size:7px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--ax-muted)}
.analyticsCommandSignal>b{display:block;font-size:11px;font-weight:750;color:var(--ax-text);margin-top:2px;overflow-wrap:anywhere}
.analyticsCommandSignal>small{display:block;font-size:9px;color:var(--ax-muted);margin-top:1px}
.analyticsCommandSignal.positive{border-left:2px solid rgba(34,197,94,.45)}
.analyticsCommandSignal.negative{border-left:2px solid rgba(239,68,68,.45)}
.analyticsCommandSignal.neutral{border-left:2px solid rgba(148,163,184,.35)}
.analyticsCommandFoot{
  display:flex;align-items:center;gap:8px;margin-top:10px;padding-top:8px;
  border-top:1px solid rgba(255,255,255,.04);
}
.analyticsCommandFoot small{font-size:9px;color:var(--ax-muted);flex:1}
.analyticsCommandProgress{flex:1;max-width:120px}
.analyticsCommandProgressBar{height:3px;border-radius:99px;background:rgba(255,255,255,.06);overflow:hidden}
.analyticsCommandProgressBar>span{display:block;height:100%;background:linear-gradient(90deg,rgba(212,166,58,.5),rgba(212,166,58,.2));border-radius:99px}
.analyticsCommandConfidence{
  font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;
  padding:3px 7px;border-radius:99px;font-style:normal;
  border:1px solid rgba(255,255,255,.08);background:rgba(255,255,255,.03);color:var(--ax-muted);
}
.analyticsCommandConfidence.good{color:#4ade80;border-color:rgba(34,197,94,.2);background:rgba(34,197,94,.08)}
.analyticsCommandConfidence.warn{color:#fbbf24;border-color:rgba(251,191,36,.2);background:rgba(251,191,36,.08)}

/* ── 2. ACTION DIRECTIVES ── */
.analyticsDirectivesGrid{
  display:grid;grid-template-columns:repeat(3,1fr);gap:8px;
}
.analyticsDirectiveCard{
  padding:10px 12px;border-radius:10px;
  background:rgba(255,255,255,.015);border:1px solid rgba(255,255,255,.05);
}
.analyticsDirectiveCard.positive{background:var(--tic-green);border-color:rgba(34,197,94,.12)}
.analyticsDirectiveCard.negative{background:var(--tic-red);border-color:rgba(239,68,68,.12)}
.analyticsDirectiveCard.warn{background:var(--tic-amber);border-color:rgba(251,191,36,.12)}
.analyticsDirectiveHead{display:flex;align-items:center;gap:5px;margin-bottom:6px}
.analyticsDirectiveHead span{
  font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.1em;color:var(--ax-muted);
}
.analyticsDirectiveSetup{
  display:block;font-size:12px;font-weight:750;color:var(--ax-text);line-height:1.3;
  overflow-wrap:anywhere;word-break:break-word;
}
.analyticsDirectiveEvidence{margin:4px 0 0;font-size:10px;color:var(--ax-muted);line-height:1.35}
.analyticsDirectiveMeta{margin-top:8px;display:flex;flex-direction:column;gap:3px}
.analyticsDirectiveMotive{font-size:9px;color:var(--ax-muted)}
.analyticsDirectiveConfidence{
  font-size:9px;font-style:normal;font-weight:650;line-height:1.3;
  padding:4px 6px;border-radius:6px;background:rgba(255,255,255,.03);
}
.analyticsDirectiveConfidence.positive{color:#4ade80}
.analyticsDirectiveConfidence.negative{color:#f87171}
.analyticsDirectiveConfidence.warn{color:#fbbf24}
.analyticsDirectiveConfidence.neutral{color:var(--ax-muted)}

/* ── 3+4. EDGE LAB + OPERATING PROFILE ── */
.analyticsIntelligenceModules{
  display:grid;grid-template-columns:1fr 1fr;gap:10px;align-items:start;
}
.analyticsEdgeLab,.analyticsOperatingProfile{
  border-radius:12px;padding:12px 14px;
  background:rgba(255,255,255,.015);border:1px solid var(--tic-border);
}
.analyticsEdgeLabHead h3,.analyticsOperatingProfileHead h3,
.analyticsPerformanceEvidenceHead h3,.analyticsWeeklyPlanHead h3{
  margin:0;font-size:13px;font-weight:800;color:var(--ax-text);
}
.analyticsEdgeLabHead p,.analyticsOperatingProfileHead p,
.analyticsPerformanceEvidenceHead p{
  margin:3px 0 0;font-size:10px;color:var(--ax-muted);line-height:1.35;
}

/* Edge Lab — Tesis activa */
.analyticsEdgeLabThesis{
  margin-top:10px;padding:10px 12px;border-radius:10px;
  background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.05);
  border-left:3px solid rgba(251,191,36,.4);
}
.analyticsEdgeLabThesis.validated{border-left-color:rgba(34,197,94,.45)}
.analyticsEdgeLabThesisHead{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}
.analyticsEdgeLabThesisHead>span{font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--ax-muted)}
.analyticsEdgeLabThesisHead>em{
  font-size:7px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;font-style:normal;
  padding:2px 6px;border-radius:99px;background:rgba(251,191,36,.1);color:#fbbf24;
}
.analyticsEdgeLabThesisHead>em.validated{background:rgba(34,197,94,.1);color:#4ade80}
.analyticsEdgeLabThesisName{display:block;font-size:13px;font-weight:800;color:var(--ax-text);line-height:1.3;overflow-wrap:anywhere}
.analyticsEdgeLabThesisMetrics{
  display:flex;flex-wrap:wrap;gap:6px 10px;margin-top:6px;
}
.analyticsEdgeLabThesisMetrics span{font-size:10px;color:var(--ax-muted)}
.analyticsEdgeLabThesisMetrics .pos{color:#4ade80;font-weight:700}
.analyticsEdgeLabThesisMetrics .neg{color:#f87171;font-weight:700}
.analyticsEdgeLabThesisProgress{margin-top:8px}
.analyticsEdgeLabThesisProgressBar{height:4px;border-radius:99px;background:rgba(255,255,255,.06);overflow:hidden}
.analyticsEdgeLabThesisProgressBar>span{display:block;height:100%;background:linear-gradient(90deg,rgba(212,166,58,.55),rgba(212,166,58,.15));border-radius:99px}
.analyticsEdgeLabThesisProgress small{display:block;margin-top:4px;font-size:9px;color:var(--ax-muted)}
.analyticsEdgeLabThesisReading{margin:6px 0 0;font-size:10px;color:var(--ax-muted);line-height:1.4}
.analyticsEdgeLabThesisEmpty{
  margin-top:10px;padding:10px 12px;border-radius:10px;
  background:rgba(255,255,255,.02);border:1px dashed rgba(255,255,255,.08);
}
.analyticsEdgeLabThesisEmpty b{display:block;font-size:11px;color:var(--ax-text)}
.analyticsEdgeLabThesisEmpty p{margin:4px 0 0;font-size:10px;color:var(--ax-muted)}

/* Edge Lab — Pipeline */
.analyticsEdgeLabPipeline{
  display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px;
}
.analyticsEdgeLabPipelineCol{
  padding:8px;border-radius:9px;background:rgba(255,255,255,.015);
  border:1px solid rgba(255,255,255,.04);min-height:80px;
}
.analyticsEdgeLabPipelineCol.warn{border-top:2px solid rgba(251,191,36,.35)}
.analyticsEdgeLabPipelineCol.negative{border-top:2px solid rgba(239,68,68,.35)}
.analyticsEdgeLabPipelineCol.neutral{border-top:2px solid rgba(148,163,184,.25)}
.analyticsEdgeLabPipelineCol.empty p{margin:6px 0 0;font-size:9px;color:var(--ax-muted)}
.analyticsEdgeLabPipelineCol h5{
  margin:0 0 6px;font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--ax-muted);
}
.analyticsEdgeLabPipelineItems{display:flex;flex-direction:column;gap:5px}
.analyticsEdgeLabPipelineItem{
  padding:5px 6px;border-radius:7px;background:rgba(255,255,255,.02);
  display:grid;grid-template-columns:1fr auto;gap:2px 6px;align-items:center;
}
.analyticsEdgeLabPipelineItem b{
  grid-column:1/-1;font-size:10px;font-weight:700;color:var(--ax-text);
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
}
.analyticsEdgeLabPipelineItem span{font-size:10px;font-weight:700}
.analyticsEdgeLabPipelineItem span.pos{color:#4ade80}
.analyticsEdgeLabPipelineItem span.neg{color:#f87171}
.analyticsEdgeLabPipelineItem small{font-size:8px;color:var(--ax-muted)}
.analyticsEdgeLabPipelineItem em{
  font-size:7px;font-style:normal;font-weight:700;text-transform:uppercase;
  color:var(--ax-muted);justify-self:end;
}
.analyticsEdgeLabCriteria{
  display:flex;flex-wrap:wrap;gap:6px 12px;margin-top:10px;padding-top:8px;
  border-top:1px solid rgba(255,255,255,.04);
}
.analyticsEdgeLabCriteria span{
  font-size:8px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;
  color:var(--ax-muted);padding:3px 7px;border-radius:99px;
  background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.05);
}

/* Operating Profile */
.analyticsOperatingProfileBody{display:flex;flex-direction:column;gap:12px;margin-top:10px}
.analyticsOperatingProfileLabel{
  display:block;font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;
  color:var(--ax-muted);margin-bottom:6px;
}
.analyticsOperatingProfileSession>b{display:block;font-size:12px;font-weight:750;color:var(--ax-text)}
.analyticsOperatingProfileData{margin:3px 0 0;font-size:10px;color:var(--ax-muted)}
.analyticsOperatingProfileBar{
  height:4px;border-radius:99px;background:rgba(255,255,255,.06);margin:8px 0;overflow:hidden;
}
.analyticsOperatingProfileBar>span{display:block;height:100%;background:linear-gradient(90deg,rgba(251,191,36,.35),rgba(251,191,36,.1));border-radius:99px}
.analyticsOperatingProfileBar.inline{height:3px;margin:4px 0 0}
.analyticsOperatingProfileBadge{
  display:inline-block;font-size:7px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;
  font-style:normal;padding:2px 6px;border-radius:99px;
  color:var(--ax-muted);background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.06);
}
.analyticsOperatingProfileBadge.warn{color:#fbbf24;border-color:rgba(251,191,36,.15)}
.analyticsOperatingProfileNote{margin:6px 0 0;font-size:10px;color:var(--ax-muted);line-height:1.4}
.analyticsOperatingProfileSessions{display:flex;flex-direction:column;gap:6px}
.analyticsOperatingProfileSessionRow{
  padding:6px 8px;border-radius:8px;background:rgba(255,255,255,.02);
}
.analyticsOperatingProfileSessionRow>div{display:flex;justify-content:space-between;align-items:baseline}
.analyticsOperatingProfileSessionRow span{font-size:11px;font-weight:700;color:var(--ax-text)}
.analyticsOperatingProfileSessionRow small{font-size:9px;color:var(--ax-muted)}
.analyticsOperatingProfileSessionRow>b{font-size:11px;font-weight:800}
.analyticsOperatingProfileSessionRow>b.pos{color:#4ade80}
.analyticsOperatingProfileSessionRow>b.neg{color:#f87171}
.analyticsOperatingProfileScore{
  display:flex;align-items:baseline;gap:4px;flex-wrap:wrap;
  padding:8px 10px;border-radius:9px;background:rgba(255,255,255,.02);
}
.analyticsOperatingProfileScore.positive{background:var(--tic-green)}
.analyticsOperatingProfileScore.negative{background:var(--tic-red)}
.analyticsOperatingProfileScore>b{font-size:20px;font-weight:800;color:var(--ax-text)}
.analyticsOperatingProfileScore>em{font-size:10px;color:var(--ax-muted);font-style:normal}
.analyticsOperatingProfileScore>p{
  width:100%;margin:4px 0 0;font-size:10px;color:var(--ax-muted);line-height:1.35;
}
.analyticsOperatingProfileFocus{display:flex;flex-direction:column;gap:5px;margin-top:8px}
.analyticsOperatingProfileFocus>div{
  display:flex;align-items:center;gap:6px;padding:6px 8px;border-radius:8px;
  background:rgba(255,255,255,.02);
}
.analyticsOperatingProfileFocus>div.positive{background:rgba(34,197,94,.08)}
.analyticsOperatingProfileFocus>div.negative{background:rgba(239,68,68,.08)}
.analyticsOperatingProfileFocus span{display:block;font-size:8px;font-weight:700;text-transform:uppercase;color:var(--ax-muted)}
.analyticsOperatingProfileFocus b{display:block;font-size:10px;font-weight:750;color:var(--ax-text)}
.analyticsOperatingProfileMetrics{
  display:grid;grid-template-columns:repeat(2,1fr);gap:5px;margin-top:8px;
}
.analyticsOperatingProfileMetrics>div{
  display:flex;align-items:center;gap:5px;padding:5px 7px;border-radius:7px;
  background:rgba(255,255,255,.02);font-size:9px;
}
.analyticsOperatingProfileMetrics span{color:var(--ax-muted);flex:1}
.analyticsOperatingProfileMetrics b{font-weight:800;color:var(--ax-text)}

/* ── 5. PERFORMANCE EVIDENCE ── */
.analyticsPerformanceEvidence{
  border-radius:12px;padding:12px 14px;
  background:rgba(255,255,255,.012);border:1px solid var(--tic-border);
}
.analyticsPerformanceEvidenceGrid{
  display:grid;grid-template-columns:1.25fr 1fr;grid-template-rows:auto auto;
  gap:8px;margin-top:10px;
}
.analyticsPerformanceEvidencePanel{
  border-radius:10px;background:rgba(255,255,255,.015);
  border:1px solid rgba(255,255,255,.05);display:flex;flex-direction:column;min-height:0;
}
.analyticsPerformanceEvidencePanel header{
  padding:8px 10px;border-bottom:1px solid rgba(255,255,255,.04);
  display:flex;justify-content:space-between;align-items:baseline;gap:8px;
}
.analyticsPerformanceEvidencePanel header h4{margin:0;font-size:11px;font-weight:800;color:var(--ax-text)}
.analyticsPerformanceEvidencePanel header span{font-size:9px;color:var(--ax-muted);white-space:nowrap}
.analyticsPerformanceEvidencePanelBody{flex:1;min-height:0;padding:6px 8px 8px}
.analyticsPerformanceEvidenceChart{width:100%;min-height:0}
.analyticsPerformanceEvidenceFallback{
  margin:0;padding:16px 10px;font-size:10px;color:var(--ax-muted);text-align:center;line-height:1.4;
}
.analyticsPerformanceEvidenceSingleR{
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  padding:20px 10px;gap:4px;
}
.analyticsPerformanceEvidenceSingleR b{font-size:18px;font-weight:800;color:var(--ax-text)}
.analyticsPerformanceEvidenceSingleR span{font-size:10px;color:var(--ax-muted)}
.analyticsPerformanceEvidencePattern{
  padding:10px;border-radius:9px;background:rgba(255,255,255,.02);
  border-left:2px solid var(--tic-gold);
}
.analyticsPerformanceEvidencePattern>span{
  display:block;font-size:8px;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--ax-muted);
}
.analyticsPerformanceEvidencePattern>b{
  display:block;margin-top:4px;font-size:12px;font-weight:750;color:var(--ax-text);overflow-wrap:anywhere;
}
.analyticsPerformanceEvidencePattern>div{
  display:flex;flex-wrap:wrap;gap:6px 10px;margin-top:8px;align-items:center;
}
.analyticsPerformanceEvidencePattern strong{font-size:12px;font-weight:800}
.analyticsPerformanceEvidencePattern strong.pos{color:#4ade80}
.analyticsPerformanceEvidencePattern strong.neg{color:#f87171}
.analyticsPerformanceEvidencePattern em{font-size:10px;color:var(--ax-muted);font-style:normal}
.analyticsPerformanceEvidencePatternList{display:flex;flex-direction:column;gap:4px}
.analyticsPerformanceEvidencePatternRow{
  display:grid;grid-template-columns:1fr auto auto;gap:6px;align-items:center;
  padding:5px 6px;border-radius:7px;background:rgba(255,255,255,.02);font-size:10px;
}
.analyticsPerformanceEvidencePatternRow span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--ax-text)}
.analyticsPerformanceEvidencePatternRow b{font-weight:800}
.analyticsPerformanceEvidencePatternRow b.pos{color:#4ade80}
.analyticsPerformanceEvidencePatternRow b.neg{color:#f87171}
.analyticsPerformanceEvidencePatternRow small{color:var(--ax-muted);white-space:nowrap}

/* ── 6. WEEKLY PLAN ── */
.analyticsWeeklyPlan{
  border-radius:12px;padding:12px 14px;
  background:linear-gradient(135deg,rgba(212,166,58,.06),rgba(255,255,255,.01));
  border:1px solid rgba(212,166,58,.15);
}
.analyticsWeeklyPlanHead{display:flex;align-items:flex-start;gap:10px}
.analyticsWeeklyPlanHead svg{color:rgba(212,166,58,.75);flex-shrink:0;margin-top:2px}
.analyticsWeeklyPlanHead p{margin:3px 0 0;font-size:10px;color:var(--ax-muted)}
.analyticsWeeklyPlanList{
  margin:10px 0 0;padding:0 0 0 18px;list-style:none;
  display:flex;flex-direction:column;gap:6px;
}
.analyticsWeeklyPlanList li{
  position:relative;font-size:11px;line-height:1.45;color:var(--ax-text);padding-left:4px;
}
.analyticsWeeklyPlanList li::before{
  content:'';position:absolute;left:-14px;top:.55em;width:5px;height:5px;
  border-radius:50%;background:rgba(212,166,58,.6);
}

/* ── RESPONSIVE 390px ── */
@media(max-width:860px){
  .analyticsCommandMain{grid-template-columns:1fr;gap:10px}
  .analyticsCommandSignals{flex-direction:row;flex-wrap:wrap}
  .analyticsCommandSignal{flex:1;min-width:100px}
  .analyticsDirectivesGrid{grid-template-columns:1fr}
  .analyticsIntelligenceModules{grid-template-columns:1fr}
  .analyticsEdgeLabPipeline{grid-template-columns:1fr}
  .analyticsPerformanceEvidenceGrid{grid-template-columns:1fr}
}

@media(max-width:390px){
  .analyticsIntelligenceFold{display:contents}
  .analyticsIntelligenceModules{display:contents}
  .analyticsIntelligenceCenter{display:flex;flex-direction:column;gap:8px}
  .analyticsCommand{order:1}
  .analyticsDirectives{order:2}
  .analyticsIntelligenceFold .analyticsSystemHealth,
  .analyticsIntelligenceCenter .analyticsSystemHealth{order:3}
  .analyticsEdgeLab{order:4}
  .analyticsOperatingProfile{order:5}
  .analyticsPerformanceEvidence{order:7}
  .analyticsWeeklyPlan{order:6}
  .analyticsIntelligenceCenter .analyticsPageHead{order:0}
  .analyticsIntelligenceCenter .analyticsFiltersBar{order:0}
}

/* ── LIGHT MODE ── */
html[data-theme="light"] .analyticsIntelligenceCenter{
  --tic-bg:rgba(15,23,42,.02);
  --tic-border:rgba(15,23,42,.08);
}
html[data-theme="light"] .analyticsCommand,
html[data-theme="light"] .analyticsEdgeLab,
html[data-theme="light"] .analyticsOperatingProfile,
html[data-theme="light"] .analyticsPerformanceEvidence{
  background:rgba(255,255,255,.95)!important;
  border-color:rgba(15,23,42,.08)!important;
}
html[data-theme="light"] .analyticsCommandScoreInner{background:#fff!important;border-color:rgba(15,23,42,.08)!important}
html[data-theme="light"] .analyticsDirectiveCard.positive{background:rgba(240,253,244,.7)!important}
html[data-theme="light"] .analyticsDirectiveCard.negative{background:rgba(255,241,242,.7)!important}
html[data-theme="light"] .analyticsDirectiveCard.warn{background:rgba(255,251,235,.7)!important}
html[data-theme="light"] .analyticsEdgeLabThesis{background:rgba(248,250,252,.8)!important;border-color:rgba(15,23,42,.06)!important}
html[data-theme="light"] .analyticsEdgeLabPipelineCol{background:rgba(248,250,252,.6)!important}
html[data-theme="light"] .analyticsOperatingProfileScore.positive{background:rgba(240,253,244,.6)!important}
html[data-theme="light"] .analyticsOperatingProfileScore.negative{background:rgba(255,241,242,.6)!important}
html[data-theme="light"] .analyticsPerformanceEvidencePanel{background:rgba(248,250,252,.5)!important}
html[data-theme="light"] .analyticsWeeklyPlan{background:linear-gradient(135deg,rgba(255,251,235,.8),rgba(255,255,255,.95))!important}
html[data-theme="light"] .analyticsEdgeLabThesisMetrics .pos{color:#15803d!important}
html[data-theme="light"] .analyticsEdgeLabThesisMetrics .neg{color:#b91c1c!important}
html[data-theme="light"] .analyticsPerformanceEvidencePattern strong.pos{color:#15803d!important}
html[data-theme="light"] .analyticsPerformanceEvidencePattern strong.neg{color:#b91c1c!important}

/* ═══════════════════════════════════════════════════════════════
   TRADING INTELLIGENCE CENTER — Visual Polish v3
   Fix: gold bleed, saturation, header chips, chart surfaces
   ═══════════════════════════════════════════════════════════════ */

/* CRITICAL: neutralize global .primary inside Analytics */
.analyticsIntelligenceCenter .primary,
.analyticsIntelligenceCenter .analyticsPerformanceEvidencePanel.primary,
.analyticsIntelligenceCenter article.primary{
  background:rgba(255,255,255,.02)!important;
  background-image:none!important;
  color:var(--ax-text)!important;
  border-color:rgba(255,255,255,.06)!important;
  box-shadow:none!important;
  font-weight:inherit!important;
}

/* Header chips — fix "ConfiabilidadInicial" merge */
.analyticsIntelligenceCenter .analyticsTopBarChip,
.analyticsShell .analyticsTopBarChip{
  display:inline-flex;
  flex-direction:column;
  align-items:flex-start;
  gap:2px;
  padding:4px 8px;
  border-radius:8px;
  background:rgba(255,255,255,.02);
  border:1px solid rgba(255,255,255,.05);
  min-width:0;
}
.analyticsIntelligenceCenter .analyticsTopBarChip em,
.analyticsShell .analyticsTopBarChip em{
  font-style:normal;
  color:var(--ax-muted);
  font-size:9px;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:.06em;
  line-height:1.2;
}
.analyticsIntelligenceCenter .analyticsTopBarChip b,
.analyticsShell .analyticsTopBarChip b{
  color:var(--ax-text);
  font-size:11px;
  font-weight:700;
  line-height:1.2;
  white-space:nowrap;
}
.analyticsIntelligenceCenter .analyticsTopBarReliability.good b{color:#4ade80}
.analyticsIntelligenceCenter .analyticsTopBarReliability.warn b{color:#fbbf24}

/* Executive Command — structured narrative */
.analyticsCommandHeadline{
  margin:0;
  font-size:15px;
  font-weight:750;
  line-height:1.35;
  color:var(--ax-text);
  max-width:52ch;
  overflow-wrap:anywhere;
}
.analyticsCommandActionRow{
  margin-top:10px;
  padding:8px 10px;
  border-radius:8px;
  background:rgba(255,255,255,.02);
  border-left:2px solid rgba(212,166,58,.35);
}
.analyticsCommandActionRow>span{
  display:block;
  font-size:8px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.08em;
  color:var(--ax-muted);
  margin-bottom:3px;
}
.analyticsCommandActionRow>p{
  margin:0;
  font-size:11px;
  font-weight:650;
  line-height:1.4;
  color:rgba(212,166,58,.88);
}
.analyticsCommandNarrative h2:not(.analyticsCommandHeadline){display:none}

/* Action Directives — neutral surfaces, semantic borders only */
.analyticsDirectiveCard{
  background:rgba(255,255,255,.02)!important;
  border:1px solid rgba(255,255,255,.06)!important;
  border-top:2px solid rgba(255,255,255,.08)!important;
}
.analyticsDirectiveCard.tone-edge{border-top-color:rgba(34,197,94,.45)!important}
.analyticsDirectiveCard.tone-leak{border-top-color:rgba(239,68,68,.45)!important}
.analyticsDirectiveCard.tone-observe{border-top-color:rgba(251,191,36,.4)!important}
.analyticsDirectiveCard.tone-neutral{border-top-color:rgba(148,163,184,.3)!important}
.analyticsDirectiveCard.positive,
.analyticsDirectiveCard.negative,
.analyticsDirectiveCard.warn{background:rgba(255,255,255,.02)!important}
.analyticsDirectiveHead svg{color:var(--ax-muted)}
.analyticsDirectiveCard.tone-edge .analyticsDirectiveHead svg{color:#4ade80}
.analyticsDirectiveCard.tone-leak .analyticsDirectiveHead svg{color:#f87171}
.analyticsDirectiveCard.tone-observe .analyticsDirectiveHead svg{color:#fbbf24}
.analyticsDirectiveConfidence{
  background:transparent!important;
  padding:0!important;
}

/* Edge Lab — pipeline breathing room */
.analyticsEdgeLabPipeline{
  grid-template-columns:repeat(auto-fit,minmax(220px,1fr))!important;
  gap:10px!important;
}
.analyticsEdgeLabPipelineItem{
  display:flex!important;
  flex-direction:column!important;
  align-items:flex-start!important;
  gap:4px!important;
  padding:7px 8px!important;
}
.analyticsEdgeLabPipelineItem b{
  white-space:normal!important;
  overflow:visible!important;
  text-overflow:unset!important;
  overflow-wrap:anywhere;
  word-break:break-word;
  width:100%;
  font-size:11px!important;
}
.analyticsEdgeLabPipelineItemMeta{
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:6px 8px;
  width:100%;
}
.analyticsEdgeLabCriteria{
  gap:4px 8px!important;
  margin-top:8px!important;
  padding-top:6px!important;
}
.analyticsEdgeLabCriteria span{
  font-size:7px!important;
  padding:2px 6px!important;
  text-transform:none!important;
  letter-spacing:.02em!important;
}

/* Operating Profile — institutional, not heavy green block */
.analyticsOperatingProfileScore{
  background:rgba(255,255,255,.02)!important;
  border:1px solid rgba(255,255,255,.05)!important;
  border-left:2px solid rgba(148,163,184,.3)!important;
  padding:8px 10px!important;
}
.analyticsOperatingProfileScore.positive{border-left-color:rgba(34,197,94,.45)!important}
.analyticsOperatingProfileScore.negative{border-left-color:rgba(239,68,68,.45)!important}
.analyticsOperatingProfileScore>b{font-size:16px!important}
.analyticsOperatingProfileBar>span{
  background:linear-gradient(90deg,rgba(148,163,184,.25),rgba(148,163,184,.08))!important;
}
.analyticsOperatingProfileFocus>div.positive{background:rgba(34,197,94,.06)!important}
.analyticsOperatingProfileFocus>div.negative{background:rgba(239,68,68,.06)!important}

/* Performance Evidence — dark premium cards, NO gold surfaces */
.analyticsPerformanceEvidencePanel{
  background:rgba(255,255,255,.02)!important;
  border:1px solid rgba(255,255,255,.06)!important;
  min-height:0;
