    linear-gradient(rgba(255,255,255,.018) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.018) 1px,transparent 1px);
  background-size:22px 22px;
  mask-image:radial-gradient(ellipse 85% 75% at 50% 40%,#000 20%,transparent 78%);
}
.analyticsSurfaceFlagship::after{
  content:'';
  position:absolute;
  inset:-20% -10% auto -10%;
  height:55%;
  pointer-events:none;
  z-index:0;
  background:radial-gradient(ellipse at 50% 0%,rgba(255,255,255,.04),transparent 62%);
  opacity:.7;
}
.analyticsSurfaceFlagship>*{position:relative;z-index:1}

.analyticsSurfaceSupport{
  position:relative;
