/* ═══════════════════════════════════════════════════════════════
   ANALYTICS REFINEMENT v14 — Collapsible filters, hero hierarchy,
   typography, edge lab, KPIs, charts, mobile-first, depth
   ═══════════════════════════════════════════════════════════════ */

.analyticsCockpit{
  --ax-type-label:11px;
  --ax-type-secondary:12px;
  --ax-type-body:14px;
  --ax-type-subtitle:15px;
  --ax-type-section:20px;
  --ax-type-kpi:28px;
  --ax-type-kpi-hero:32px;
  --ax-rhythm:16px;
  --ax-touch:44px;
}

/* ── 1. Collapsible filters panel ── */
.analyticsFiltersPanel{
  display:flex;
  flex-direction:column;
  gap:0;
  min-width:0;
}
.analyticsFiltersToggle{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  width:100%;
  min-height:var(--ax-touch);
  padding:8px 12px;
  border:1px solid rgba(255,255,255,.07);
  border-radius:12px;
  background:linear-gradient(168deg,rgba(18,24,36,.88),rgba(10,13,20,.94));
  color:inherit;
  cursor:pointer;
  text-align:left;
  transition:border-color .18s ease,background .18s ease;
}
.analyticsFiltersToggle:hover{
  border-color:rgba(255,255,255,.12);
  background:linear-gradient(168deg,rgba(22,28,42,.92),rgba(12,16,24,.96));
}
.analyticsFiltersToggleLead{
  display:flex;
  align-items:center;
  gap:8px;
  min-width:0;
  flex:1;
}
.analyticsFiltersToggleLabel{
  flex-shrink:0;
  font-size:11px;
  font-weight:850;
  text-transform:uppercase;
  letter-spacing:.08em;
  color:var(--ax-muted,var(--muted2));
}
.analyticsFiltersToggleSummary{
  font-size:13px;
  font-weight:600;
  color:var(--ax-text-hi,var(--ax-text));
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  min-width:0;
  line-height:1.35;
}
.analyticsFiltersToggleChevron{
  flex-shrink:0;
  color:var(--ax-muted);
  opacity:.75;
  transition:transform .22s ease;
}
.analyticsFiltersPanel.is-expanded .analyticsFiltersToggleChevron{
  transform:rotate(180deg);
}
.analyticsFiltersPanel.is-expanded .analyticsFiltersToggle{
  border-radius:12px 12px 0 0;
  border-bottom-color:rgba(255,255,255,.04);
}
.analyticsFiltersActiveChips{
  display:flex;
  flex-wrap:wrap;
  gap:6px;
  padding:6px 12px 8px;
  border:1px solid rgba(255,255,255,.06);
  border-top:none;
  border-radius:0 0 12px 12px;
  background:rgba(0,0,0,.12);
}
.analyticsFiltersActiveChip{
  display:inline-flex;
  align-items:center;
  gap:5px;
  padding:4px 9px;
  border-radius:99px;
  border:1px solid rgba(255,255,255,.08);
  background:rgba(255,255,255,.03);
  max-width:100%;
  min-width:0;
}
.analyticsFiltersActiveChip em{
  font-style:normal;
  font-size:10px;
  font-weight:750;
  text-transform:uppercase;
  letter-spacing:.05em;
  color:var(--ax-muted);
  flex-shrink:0;
}
.analyticsFiltersActiveChip b{
  font-size:12px;
  font-weight:700;
  color:var(--ax-text-hi,var(--ax-text));
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  min-width:0;
}
.analyticsFiltersBody{
  padding:12px 12px 14px;
  border:1px solid rgba(255,255,255,.06);
  border-top:none;
  border-radius:0 0 12px 12px;
  background:linear-gradient(180deg,rgba(0,0,0,.1),rgba(0,0,0,.16));
}
.analyticsFiltersBody .analyticsFiltersCompactGrid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:10px 12px;
}
.analyticsFiltersPanel.is-expanded .analyticsFiltersBody{
  border-top:1px solid rgba(255,255,255,.04);
}
.analyticsCockpit .analyticsFiltersCompactGrid{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:10px 12px;
}
.analyticsCockpit .analyticsFilterField>span{
  font-size:var(--ax-type-label)!important;
  line-height:1.35;
  letter-spacing:.05em;
}
.analyticsCockpit .analyticsFilterField .input.small{
  min-height:var(--ax-touch);
