/* ═══════════════════════════════════════════════════════════════
   AURORA AMBIENT LAYER v17 — HTML mockup parity
   .auroraAmbient + orbs (aurora-v3 / laboratorio-edge)
   ═══════════════════════════════════════════════════════════════ */

.auroraAmbient{
  position:fixed;
  inset:0;
  z-index:0;
  pointer-events:none;
  filter:blur(80px);
  opacity:.42;
  overflow:hidden;
}
.auroraOrb{
  position:absolute;
  border-radius:50%;
}
.auroraOrb--violet{
  width:560px;
  height:560px;
  background:var(--violet,#7C5CFF);
  top:-160px;
  left:-120px;
  animation:auroraFloat1 24s ease-in-out infinite;
}
.auroraOrb--cyan{
  width:460px;
  height:460px;
  background:var(--cyan,#33E6C4);
  top:30%;
  right:-180px;
  animation:auroraFloat2 28s ease-in-out infinite;
}
.auroraOrb--magenta{
  width:420px;
  height:420px;
  background:var(--magenta,#FF4FA3);
  bottom:-160px;
  left:30%;
  opacity:.5;
  animation:auroraFloat3 26s ease-in-out infinite;
}
@keyframes auroraFloat1{
  0%,100%{transform:translate(0,0)}
  50%{transform:translate(60px,40px)}
}
@keyframes auroraFloat2{
  0%,100%{transform:translate(0,0)}
  50%{transform:translate(-50px,60px)}
}
@keyframes auroraFloat3{
  0%,100%{transform:translate(0,0)}
  50%{transform:translate(40px,-50px)}
}
