  --aurora-shadow-flagship:0 18px 52px rgba(0,0,0,.24),inset 0 1px 0 rgba(255,255,255,.04);
  --aurora-shadow-compact:0 8px 24px rgba(0,0,0,.16),inset 0 1px 0 rgba(255,255,255,.025);
